import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Counter, Rate, Trend } from 'k6/metrics';
import { parseHTML } from 'k6/html';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

// Custom metrics
const businessFailureRate = new Rate('business_failure');
const unexpectedFailures = new Counter('unexpected_failures');
const businessResponses = new Counter('business_responses');

// Configuration
const USERS = 2;
const ITERATIONS = 2;
const MAX_PAGES = 3;
const MAX_POLLS = 5;
const POLL_INTERVAL_MS = 50;
const MAX_RETRIES_429 = 4;
const RETRY_AFTER_MS = 1000;

// Helper: extract CSRF from HTML form
function extractCsrfFromForm(htmlContent) {
  const doc = parseHTML(htmlContent);
  const csrfInput = doc.find('input[name="csrf"]');
  if (csrfInput.length > 0) {
    return csrfInput.attr('value');
  }
  return null;
}

// Helper: extract challenge from HTML form
function extractChallengeFromForm(htmlContent) {
  const doc = parseHTML(htmlContent);
  const challengeInput = doc.find('input[name="challenge"]');
  if (challengeInput.length > 0) {
    return challengeInput.attr('value');
  }
  return null;
}

// Helper: extract form action
function extractFormAction(htmlContent) {
  const doc = parseHTML(htmlContent);
  const form = doc.find('form');
  if (form.length > 0) {
    return form.attr('action');
  }
  return null;
}

// Helper: extract Location header
function extractLocation(response) {
  return response.headers['Location'];
}

// Helper: extract ETag
function extractETag(response) {
  return response.headers['ETag'];
}

// Helper: extract JSON body
function getJsonBody(response) {
  try {
    return response.json();
  } catch (e) {
    return null;
  }
}

// Helper: check if response is 401 with specific error
function is401WithError(response, errorType) {
  if (response.status !== 401) return false;
  const body = getJsonBody(response);
  return body && body.error === errorType;
}

// Helper: handle 429 retry
function handle429WithRetry(requestFn, maxRetries = MAX_RETRIES_429) {
  let response = requestFn();
  let retries = 0;

  while (response.status === 429 && retries < maxRetries) {
    const retryAfter = response.headers['Retry-After'];
    const waitMs = retryAfter ? parseInt(retryAfter) * 1000 : RETRY_AFTER_MS;
    sleep(waitMs / 1000);
    response = requestFn();
    retries++;
  }

  return response;
}

// Helper: perform work/browse with retry
function performWork(csrfToken, sessionCookies) {
  const workUrl = `${BASE_URL}/v2/work`;
  const headers = {
    'X-CSRF-Token': csrfToken,
    'Content-Type': 'application/json',
  };

  const requestFn = () => http.post(workUrl, JSON.stringify({}), { headers, cookies: sessionCookies });
  const response = handle429WithRetry(requestFn);

  businessResponses.add(1);
  if (response.status !== 200) {
    unexpectedFailures.add(1);
    businessFailureRate.add(1);
  } else {
    businessFailureRate.add(0);
  }

  return response;
}

// Helper: handle 401 expiry - renew session
function handle401Expiry(response, csrfToken, sessionCookies, cartId) {
  const renewUrl = `${BASE_URL}/v2/session/renew`;
  const headers = {
    'X-CSRF-Token': csrfToken,
    'Content-Type': 'application/json',
  };

  const renewResponse = http.post(renewUrl, JSON.stringify({}), { headers, cookies: sessionCookies });

  if (renewResponse.status === 200) {
    const renewBody = getJsonBody(renewResponse);
    const newCsrf = renewBody.csrf || csrfToken;

    // Recover cart if exists
    if (cartId) {
      const recoverUrl = `${BASE_URL}/v2/carts/${cartId}/recover`;
      const recoverHeaders = {
        'X-CSRF-Token': newCsrf,
        'Content-Type': 'application/json',
      };
      http.post(recoverUrl, JSON.stringify({}), { headers: recoverHeaders, cookies: sessionCookies });
    }

    return { csrf: newCsrf, recovered: true };
  }

  return { csrf: csrfToken, recovered: false };
}

// Helper: handle 401 session revoked - fresh login
function handle401SessionRevoked(csrfToken, sessionCookies, cartId) {
  // Get fresh form
  const loginFormResponse = http.get(`${BASE_URL}/v2/login-form`);
  const newCsrf = extractCsrfFromForm(loginFormResponse.body);

  if (!newCsrf) {
    return { csrf: csrfToken, recovered: false };
  }

  // Fresh login
  const loginUrl = `${BASE_URL}/v2/login`;
  const loginHeaders = {
    'Content-Type': 'application/json',
  };
  const loginPayload = JSON.stringify({
    username: `bench-${__VU}`,
    password: 'bench',
    csrf: newCsrf,
  });

  const loginResponse = http.post(loginUrl, loginPayload, { headers: loginHeaders });

  if (loginResponse.status === 200 || loginResponse.status === 302) {
    let finalCsrf = newCsrf;
    let finalCookies = sessionCookies;

    if (loginResponse.status === 200) {
      const loginBody = getJsonBody(loginResponse);
      finalCsrf = loginBody.csrf || newCsrf;
    } else if (loginResponse.status === 302) {
      const location = extractLocation(loginResponse);
      if (location) {
        const locationResponse = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`);
        const locationBody = getJsonBody(locationResponse);
        if (locationBody && locationBody.csrf) {
          finalCsrf = locationBody.csrf;
        }
      }
    }

    // Recover cart
    if (cartId) {
      const recoverUrl = `${BASE_URL}/v2/carts/${cartId}/recover`;
      const recoverHeaders = {
        'X-CSRF-Token': finalCsrf,
        'Content-Type': 'application/json',
      };
      http.post(recoverUrl, JSON.stringify({}), { headers: recoverHeaders, cookies: finalCookies });
    }

    return { csrf: finalCsrf, recovered: true };
  }

  return { csrf: csrfToken, recovered: false };
}

// Helper: handle 401 with retry logic
function handle401WithRetry(response, csrfToken, sessionCookies, cartId, retryFn) {
  const body = getJsonBody(response);

  if (body && body.error === 'expired') {
    const result = handle401Expiry(response, csrfToken, sessionCookies, cartId);
    if (result.recovered) {
      return retryFn(result.csrf);
    }
  } else if (body && body.error === 'session') {
    const result = handle401SessionRevoked(csrfToken, sessionCookies, cartId);
    if (result.recovered) {
      return retryFn(result.csrf);
    }
  } else if (body && body.error === 'denied') {
    // Denied is not expiry - fail assertion
    check(response, { 'not denied': (r) => false });
  }

  return response;
}

// Helper: get catalog with pagination
function getCatalog(csrfToken, sessionCookies) {
  const products = [];
  let nextUrl = null;
  let pagesTraversed = 0;

  // First page
  const catalogUrl = `${BASE_URL}/v2/catalog`;
  const catalogResponse = http.get(catalogUrl, { cookies: sessionCookies });

  if (catalogResponse.status === 200) {
    const catalogBody = getJsonBody(catalogResponse);
    if (catalogBody && catalogBody.data && catalogBody.data.products) {
      products.push(...catalogBody.data.products);
    }
    nextUrl = catalogBody && catalogBody.next ? catalogBody.next : null;
  }

  // Traverse additional pages
  while (nextUrl && pagesTraversed < MAX_PAGES) {
    const pageUrl = nextUrl.startsWith('http') ? nextUrl : `${BASE_URL}${nextUrl}`;
    const pageResponse = http.get(pageUrl, { cookies: sessionCookies });

    if (pageResponse.status === 200) {
      const pageBody = getJsonBody(pageResponse);
      if (pageBody && pageBody.data && pageBody.data.products) {
        products.push(...pageBody.data.products);
      }
      nextUrl = pageBody && pageBody.next ? pageBody.next : null;
    } else {
      break;
    }

    pagesTraversed++;
  }

  return products;
}

// Helper: get challenge and grant
function getChallengeAndGrant(csrfToken, sessionCookies) {
  const challengeFormUrl = `${BASE_URL}/v2/challenge-form`;
  const challengeFormResponse = http.get(challengeFormUrl, { cookies: sessionCookies });

  if (challengeFormResponse.status !== 200) {
    return null;
  }

  const challenge = extractChallengeFromForm(challengeFormResponse.body);
  const formAction = extractFormAction(challengeFormResponse.body);

  if (!challenge || !formAction) {
    return null;
  }

  const challengeUrl = formAction.startsWith('http') ? formAction : `${BASE_URL}${formAction}`;
  const challengeHeaders = {
    'X-CSRF-Token': csrfToken,
    'Content-Type': 'application/json',
  };
  const challengePayload = JSON.stringify({ challenge });

  const challengeResponse = http.post(challengeUrl, challengePayload, { headers: challengeHeaders, cookies: sessionCookies });

  if (challengeResponse.status === 302) {
    const location = extractLocation(challengeResponse);
    if (location) {
      const grantUrl = location.startsWith('http') ? location : `${BASE_URL}${location}`;
      const grantResponse = http.get(grantUrl, { cookies: sessionCookies });

      if (grantResponse.status === 200) {
        const grantBody = getJsonBody(grantResponse);
        return grantBody;
      }
    }
  } else if (challengeResponse.status === 200) {
    const challengeBody = getJsonBody(challengeResponse);
    return challengeBody;
  }

  return null;
}

// Helper: create reservation
function createReservation(cartId, csrfToken, sessionCookies) {
  const reservationUrl = `${BASE_URL}/v2/reservations`;
  const headers = {
    'X-CSRF-Token': csrfToken,
    'Content-Type': 'application/json',
  };
  const payload = JSON.stringify({ cart_id: cartId });

  const response = http.post(reservationUrl, payload, { headers, cookies: sessionCookies });

  if (response.status === 202) {
    const body = getJsonBody(response);
    if (body && body.status_url) {
      // Poll for status
      let pollCount = 0;
      let statusUrl = body.status_url;
      let reservationId = null;
      let finalCsrf = body.csrf || csrfToken;

      while (pollCount < MAX_POLLS) {
        sleep(POLL_INTERVAL_MS / 1000);
        const pollUrl = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
        const pollResponse = http.get(pollUrl, { cookies: sessionCookies });

        if (pollResponse.status === 200) {
          const pollBody = getJsonBody(pollResponse);
          if (pollBody && pollBody.status === 'ready' && pollBody.reservation_id) {
            reservationId = pollBody.reservation_id;
            if (pollBody.csrf) {
              finalCsrf = pollBody.csrf;
            }
            break;
          } else if (pollBody && pollBody.status === 'failed') {
            break;
          }
          // pending - continue polling
        }

        pollCount++;
      }

      return { reservationId, csrf: finalCsrf };
    }
  }

  return { reservationId: null, csrf: csrfToken };
}

// Main journey function
function shopJourney() {
  const username = `bench-${__VU}`;
  const password = 'bench';

  // Step 1: GET login form to get CSRF
  const loginFormUrl = `${BASE_URL}/v2/login-form`;
  const loginFormResponse = http.get(loginFormUrl);

  check(loginFormResponse, {
    'login form loads': (r) => r.status === 200,
  });

  const csrfToken = extractCsrfFromForm(loginFormResponse.body);

  check(csrfToken, {
    'CSRF token extracted': (t) => t !== null && t !== undefined && t !== '',
  });

  if (!csrfToken) {
    return;
  }

  // Step 2: POST login
  const loginUrl = `${BASE_URL}/v2/login`;
  const loginHeaders = {
    'Content-Type': 'application/json',
  };
  const loginPayload = JSON.stringify({
    username,
    password,
    csrf: csrfToken,
  });

  const loginResponse = http.post(loginUrl, loginPayload, { headers: loginHeaders });

  let sessionCookies = {};
  let currentCsrf = csrfToken;

  if (loginResponse.status === 200) {
    const loginBody = getJsonBody(loginResponse);
    currentCsrf = loginBody.csrf || csrfToken;
    sessionCookies = loginResponse.cookies;
  } else if (loginResponse.status === 302) {
    const location = extractLocation(loginResponse);
    if (location) {
      const locationUrl = location.startsWith('http') ? location : `${BASE_URL}${location}`;
      const locationResponse = http.get(locationUrl);
      const locationBody = getJsonBody(locationResponse);
      if (locationBody && locationBody.csrf) {
        currentCsrf = locationBody.csrf;
      }
      sessionCookies = locationResponse.cookies;
    }
  }

  check(loginResponse, {
    'login successful': (r) => r.status === 200 || r.status === 302,
  });

  // Step 3: Get catalog
  const products = getCatalog(currentCsrf, sessionCookies);

  check(products.length > 0, {
    'catalog has products': (p) => p === true,
  });

  if (products.length === 0) {
    return;
  }

  // Step 4: Get challenge and grant (optional but try)
  let grantId = null;
  const grantResult = getChallengeAndGrant(currentCsrf, sessionCookies);
  if (grantResult && grantResult.grant_id) {
    grantId = grantResult.grant_id;
    if (grantResult.csrf) {
      currentCsrf = grantResult.csrf;
    }
  }

  // Step 5: Create cart
  const firstProduct = products[0];
  const firstVariant = firstProduct.variants && firstProduct.variants.length > 0 ? firstProduct.variants[0] : null;

  if (!firstVariant || !firstVariant.in_stock) {
    // Find first in-stock variant
    let found = false;
    for (const product of products) {
      if (product.variants) {
        for (const variant of product.variants) {
          if (variant.in_stock) {
            firstProduct.id = product.id;
            firstVariant.id = variant.id;
            firstVariant.in_stock = true;
            found = true;
            break;
          }
        }
      }
      if (found) break;
    }
  }

  if (!firstVariant || !firstVariant.in_stock) {
    return;
  }

  const cartUrl = `${BASE_URL}/v2/carts`;
  const cartHeaders = {
    'X-CSRF-Token': currentCsrf,
    'Content-Type': 'application/json',
  };
  const cartPayload = {
    product_id: firstProduct.id,
    variant_id: firstVariant.id,
  };
  if (grantId) {
    cartPayload.grant_id = grantId;
  }

  let cartResponse = http.post(cartUrl, JSON.stringify(cartPayload), { headers: cartHeaders, cookies: sessionCookies });

  // Handle 401
  if (cartResponse.status === 401) {
    cartResponse = handle401WithRetry(cartResponse, currentCsrf, sessionCookies, null, (newCsrf) => {
      currentCsrf = newCsrf;
      const retryHeaders = {
        'X-CSRF-Token': newCsrf,
        'Content-Type': 'application/json',
      };
      return http.post(cartUrl, JSON.stringify(cartPayload), { headers: retryHeaders, cookies: sessionCookies });
    });
  }

  check(cartResponse, {
    'cart created': (r) => r.status === 201,
  });

  if (cartResponse.status !== 201) {
    return;
  }

  const cartBody = getJsonBody(cartResponse);
  const cartId = cartBody.id;
  if (cartBody.csrf) {
    currentCsrf = cartBody.csrf;
  }
  let cartETag = extractETag(cartResponse);

  // Step 6: GET cart to get ETag
  const getCartUrl = `${BASE_URL}/v2/carts/${cartId}`;
  let getCartResponse = http.get(getCartUrl, { cookies: sessionCookies });

  if (getCartResponse.status === 401) {
    getCartResponse = handle401WithRetry(getCartResponse, currentCsrf, sessionCookies, cartId, (newCsrf) => {
      currentCsrf = newCsrf;
      return http.get(getCartUrl, { cookies: sessionCookies });
    });
  }

  if (getCartResponse.status === 200) {
    cartETag = extractETag(getCartResponse);
  }

  // Step 7: PATCH cart (update quantity)
  const patchUrl = `${BASE_URL}/v2/carts/${cartId}`;
  const patchHeaders = {
    'X-CSRF-Token': currentCsrf,
    'Content-Type': 'application/json',
  };
  if (cartETag) {
    patchHeaders['If-Match'] = cartETag;
  }
  const patchPayload = JSON.stringify({ quantity: 2 });

  let patchResponse = http.patch(patchUrl, patchPayload, { headers: patchHeaders, cookies: sessionCookies });

  // Handle 412 - re-read and retry
  if (patchResponse.status === 412) {
    const reReadResponse = http.get(getCartUrl, { cookies: sessionCookies });
    if (reReadResponse.status === 200) {
      cartETag = extractETag(reReadResponse);
      patchHeaders['If-Match'] = cartETag;
      patchResponse = http.patch(patchUrl, patchPayload, { headers: patchHeaders, cookies: sessionCookies });
    }
  }

  // Handle 401
  if (patchResponse.status === 401) {
    patchResponse = handle401WithRetry(patchResponse, currentCsrf, sessionCookies, cartId, (newCsrf) => {
      currentCsrf = newCsrf;
      const retryHeaders = {
        'X-CSRF-Token': newCsrf,
        'Content-Type': 'application/json',
      };
      if (cartETag) {
        retryHeaders['If-Match'] = cartETag;
      }
      return http.patch(patchUrl, patchPayload, { headers: retryHeaders, cookies: sessionCookies });
    });
  }

  check(patchResponse, {
    'cart patched': (r) => r.status === 200 || r.status === 204,
  });

  if (patchResponse.status === 200) {
    const patchBody = getJsonBody(patchResponse);
    if (patchBody && patchBody.csrf) {
      currentCsrf = patchBody.csrf;
    }
  }

  // Step 8: Create reservation
  const reservationResult = createReservation(cartId, currentCsrf, sessionCookies);
  let reservationId = reservationResult.reservationId;
  if (reservationResult.csrf) {
    currentCsrf = reservationResult.csrf;
  }

  // Step 9: Create order
  const orderUrl = `${BASE_URL}/v2/orders`;
  const orderHeaders = {
    'X-CSRF-Token': currentCsrf,
    'Content-Type': 'application/json',
    'Idempotency-Key': `order-${cartId}-${__VU}-${__ITER}`,
  };
  if (cartETag) {
    orderHeaders['If-Match'] = cartETag;
  }
  const orderPayload = {
    cart_id: cartId,
  };
  if (reservationId) {
    orderPayload.reservation_id = reservationId;
  }

  let orderResponse = http.post(orderUrl, JSON.stringify(orderPayload), { headers: orderHeaders, cookies: sessionCookies });

  // Handle 401
  if (orderResponse.status === 401) {
    orderResponse = handle401WithRetry(orderResponse, currentCsrf, sessionCookies, cartId, (newCsrf) => {
      currentCsrf = newCsrf;
      const retryHeaders = {
        'X-CSRF-Token': newCsrf,
        'Content-Type': 'application/json',
        'Idempotency-Key': `order-${cartId}-${__VU}-${__ITER}`,
      };
      if (cartETag) {
        retryHeaders['If-Match'] = cartETag;
      }
      return http.post(orderUrl, JSON.stringify(orderPayload), { headers: retryHeaders, cookies: sessionCookies });
    });
  }

  check(orderResponse, {
    'order created': (r) => r.status === 201,
  });

  if (orderResponse.status === 201) {
    const orderBody = getJsonBody(orderResponse);
    check(orderBody, {
      'order accepted': (b) => b && b.accepted === true,
    });
    if (orderBody && orderBody.csrf) {
      currentCsrf = orderBody.csrf;
    }
  } else if (orderResponse.status === 200) {
    const orderBody = getJsonBody(orderResponse);
    check(orderBody, {
      'order accepted (200)': (b) => b && b.accepted === true,
    });
  }

  // Step 10: Perform work
  performWork(currentCsrf, sessionCookies);
}

export const options = {
  scenarios: {
    shop_flow: {
      executor: 'per-vu-iterations',
      vus: USERS,
      iterations: ITERATIONS,
      maxDuration: '5m',
    },
  },
  thresholds: {
    business_failure: ['rate<0.1'],
  },
};

export default function () {
  shopJourney();
  sleep(1);
}
