```javascript
import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Rate, Trend } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const businessFailure = new Rate('business_failure');
const loginDuration = new Trend('login_duration', true);
const checkoutDuration = new Trend('checkout_duration', true);

const PROFILES = [
  { login_csrf: true },
  { login_csrf: true, html_layout: 1, reverse_catalog: true }
];

function extractCsrfFromHtml(html) {
  // Match input elements with name="csrf" regardless of attribute order
  const patterns = [
    /<input[^>]*name=["']csrf["'][^>]*>/i,
    /<input[^>]*value=["'][^"']*["'][^>]*name=["']csrf["'][^>]*>/i
  ];

  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match) {
      const inputTag = match[0];
      const valueMatch = inputTag.match(/value=["']([^"']*)["']/i);
      if (valueMatch) {
        return valueMatch[1];
      }
    }
  }

  // Fallback: try to find any input with name=csrf
  const allInputs = html.match(/<input[^>]*>/gi) || [];
  for (const input of allInputs) {
    if (/name=["']csrf["']/i.test(input)) {
      const valueMatch = input.match(/value=["']([^"']*)["']/i);
      if (valueMatch) {
        return valueMatch[1];
      }
    }
  }

  return null;
}

function extractNonceFromHtml(html) {
  const nonceMatch = html.match(/name=["']login_nonce["'][^>]*value=["']([^"']*)["']/i) ||
                     html.match(/value=["']([^"']*)["'][^>]*name=["']login_nonce["']/i);
  return nonceMatch ? nonceMatch[1] : null;
}

function extractChallengeAction(html) {
  const formMatch = html.match(/<form[^>]*action=["']([^"']*challenges[^"']*)["'][^>]*>/i);
  if (formMatch) {
    return formMatch[1];
  }
  return null;
}

function extractChallengeInput(html) {
  const inputMatch = html.match(/<input[^>]*name=["']challenge["'][^>]*>/i);
  if (inputMatch) {
    const valueMatch = inputMatch[0].match(/value=["']([^"']*)["']/i);
    return valueMatch ? valueMatch[1] : null;
  }
  return null;
}

function extractGrantIdFromLocation(html) {
  const grantMatch = html.match(/grant_id["']?\s*[:=]\s*["']([^"']+)["']/i);
  return grantMatch ? grantMatch[1] : null;
