        const recoverResult = recoverCart(cookies, csrf, cartId);
        if (recoverResult.success) {
          cookies = recoverResult.cookies;
          csrf = recoverResult.csrf;
        }
      }
      return { retry: true, cookies, csrf, error: null };
    }
    // Renew failed, try fresh login
    const loginResult = login('bench', 'bench', {});
    if (loginResult.success) {
      cookies = loginResult.cookies;
      csrf = loginResult.csrf;
      if (cartId) {
        const recoverResult = recoverCart(cookies, csrf, cartId);
        if (recoverResult.success) {
          cookies = recoverResult.cookies;
          csrf = recoverResult.csrf;
        }
      }
      return { retry: true, cookies, csrf, error: null };
    }
    return { retry: false, cookies, csrf, error: 'session expired and recovery failed' };
  }
  if (errorCode === 'session') {
    // Session revoked, fresh login
    const loginResult = login('bench', 'bench', {});
    if (loginResult.success) {
      cookies = loginResult.cookies;
      csrf = loginResult.csrf;
      if (cartId) {
        const recoverResult = recoverCart(cookies, csrf, cartId);
        if (recoverResult.success) {
          cookies = recoverResult.cookies;
          csrf = recoverResult.csrf;
        }
      }
      return { retry: true, cookies, csrf, error: null };
    }
    return { retry: false, cookies, csrf, error: 'session revoked and recovery failed' };
  }
  if (errorCode === 'denied') {
    return { retry: false, cookies, csrf, error: 'denied' };
  }
  return { retry: false, cookies, csrf, error: `unknown 401 error ${errorCode}` };
}

function getCatalog(cookies, csrf, profile) {
