function selectEligibleProduct(cookies, csrf, profile) {
  // Try main catalog first
  const catalogResult = getCatalog(cookies, csrf, profile);
  if (!catalogResult.success) {
    return { success: false, product: null, variantId: null, productId: null, cookies, csrf, error: catalogResult.error };
  }
  cookies = catalogResult.cookies;
  csrf = catalogResult.csrf;
  const json = catalogResult.json;
  const product = getProductFromJson(json);
  if (product) {
    const variantId = getInStockVariantId(product);
    const productId = getProductId(product);
    if (variantId && productId) {
      return { success: true, product, variantId, productId, cookies, csrf, error: null };
    }
  }
  // Traverse pages
  let next = getNextFromJson(json);
  let pagesTraversed = 0;
  while (next && pagesTraversed < 3) {
    const pageResult = getCatalogPage(cookies, csrf, next, profile);
    if (!pageResult.success) {
      return { success: false, product: null, variantId: null, productId: null, cookies, csrf, error: pageResult.error };
    }
    cookies = pageResult.cookies;
    csrf = pageResult.csrf;
    const pageJson = pageResult.json;
    const pageProduct = getProductFromJson(pageJson);
    if (pageProduct) {
      const variantId = getInStockVariantId(pageProduct);
      const productId = getProductId(pageProduct);
      if (variantId && productId) {
        return { success: true, product: pageProduct, variantId, productId, cookies, csrf, error: null };
      }
    }
    next = getNextFromJson(pageJson);
    pagesTraversed++;
  }
  return { success: false, product: null, variantId: null, productId: null, cookies, csrf, error: 'no in-stock product found' };
}

