function patchCart(cookies, csrf, cartId, etag, quantity, profile) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'If-Match': etag,
  };
  const body = JSON.stringify({ quantity: quantity });
  const res = makeRequest('PATCH', `${BASE_URL}/v2/carts/${cartId}`, body, headers, cookies, 0);
  if (res.status === 200) {
    mergeCookies(cookies, extractSetCookies(res.headers));
    const json = res.json();
    const newCsrf = getCsrfFromJson(json) || csrf;
    const newEtag = getEtag(res.headers);
    return { success: true, etag: newEtag, cookies, csrf: newCsrf, error: null };
  }
  if (res.status === 412) {
    // Re-read and retry once
    const getResult = getCart(cookies, csrf, cartId, profile);
    if (!getResult.success) {
      return { success: false, etag: null, cookies, csrf, error: getResult.error };
    }
    cookies = getResult.cookies;
    csrf = getResult.csrf;
    const newEtag = getResult.etag;
    const retryHeaders = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': newEtag,
    };
    const retryRes = makeRequest('PATCH', `${BASE_URL}/v2/carts/${cartId}`, body, retryHeaders, cookies, 0);
    if (retryRes.status === 200) {
      mergeCookies(cookies, extractSetCookies(retryRes.headers));
      const json = retryRes.json();
      const newCsrf = getCsrfFromJson(json) || csrf;
      const finalEtag = getEtag(retryRes.headers);
      return { success: true, etag: finalEtag, cookies, csrf: newCsrf, error: null };
    }
    if (retryRes.status === 401) {
      const handled = handle401(retryRes, cookies, csrf, cartId, 'patch-cart');
      if (handled.retry) {
        const getResult2 = getCart(handled.cookies, handled.csrf, cartId, profile);
        if (!getResult2.success) {
          return { success: false, etag: null, cookies: handled.cookies, csrf: handled.csrf, error: getResult2.error };
        }
        const retryHeaders2 = {
          'Content-Type': 'application/json',
          'X-CSRF-Token': handled.csrf,
          'If-Match': getResult2.etag,
        };
        const retryRes2 = makeRequest('PATCH', `${BASE_URL}/v2/carts/${cartId}`, body, retryHeaders2, handled.cookies, 0);
        if (retryRes2.status === 200) {
          mergeCookies(handled.cookies, extractSetCookies(retryRes2.headers));
          const json = retryRes2.json();
          const newCsrf = getCsrfFromJson(json) || handled.csrf;
          const finalEtag = getEtag(retryRes2.headers);
          return { success: true, etag: finalEtag, cookies: handled.cookies, csrf: newCsrf, error: null };
        }
        return { success: false, etag: null, cookies: handled.cookies, csrf: handled.csrf, error: `patch-cart retry2 status ${retryRes2.status}` };
      }
      return { success: false, etag: null, cookies, csrf, error: handled.error };
    }
    return { success: false, etag: null, cookies, csrf, error: `patch-cart retry status ${retryRes.status}` };
  }
  if (res.status === 401) {
    const handled = handle401(res, cookies, csrf, cartId, 'patch-cart');
    if (handled.retry) {
      const getResult = getCart(handled.cookies, handled.csrf, cartId, profile);
      if (!getResult.success) {
        return { success: false, etag: null, cookies: handled.cookies, csrf: handled.csrf, error: getResult.error };
      }
      const retryHeaders = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': handled.csrf,
        'If-Match': getResult.etag,
      };
      const retryRes = makeRequest('PATCH', `${BASE_URL}/v2/carts/${cartId}`, body, retryHeaders, handled.cookies, 0);
      if (retryRes.status === 200) {
        mergeCookies(handled.cookies, extractSetCookies(retryRes.headers));
        const json = retryRes.json();
        const newCsrf = getCsrfFromJson(json) || handled.csrf;
        const finalEtag = getEtag(retryRes.headers);
        return { success: true, etag: finalEtag, cookies: handled.cookies, csrf: newCsrf, error: null };
      }
      return { success: false, etag: null, cookies: handled.cookies, csrf: handled.csrf, error: `patch-cart retry status ${retryRes.status}` };
    }
    return { success: false, etag: null, cookies, csrf, error: handled.error };
  }
  return { success: false, etag: null, cookies, csrf, error: `patch-cart status ${res.status}` };
}

