function postChallenge(cookies, csrf, action, challengeValue, profile) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };
  const body = JSON.stringify({ challenge: challengeValue });
  const res = makeRequest('POST', `${BASE_URL}${action}`, body, headers, cookies, 0);
  if (res.status === 302) {
    const loc = getLocationFromHeaders(res.headers);
    if (loc) {
      const locRes = makeRequest('GET', `${BASE_URL}${loc}`, null, headers, cookies, 0);
      mergeCookies(cookies, extractSetCookies(locRes.headers));
      if (locRes.status === 200) {
        const json = locRes.json();
        const grantId = getGrantId(locRes.body);
        const newCsrf = getCsrfFromJson(json) || csrf;
        return { success: true, grantId, cookies, csrf: newCsrf, error: null };
      }
      return { success: false, grantId: null, cookies, csrf, error: `challenge location status ${locRes.status}` };
    }
    return { success: false, grantId: null, cookies, csrf, error: 'no location in challenge response' };
  }
  if (res.status === 401) {
    const handled = handle401(res, cookies, csrf, null, 'challenge');
    if (handled.retry) {
      const retryRes = makeRequest('POST', `${BASE_URL}${action}`, body, headers, handled.cookies, 0);
      if (retryRes.status === 302) {
        const loc = getLocationFromHeaders(retryRes.headers);
        if (loc) {
          const locRes = makeRequest('GET', `${BASE_URL}${loc}`, null, headers, handled.cookies, 0);
          mergeCookies(handled.cookies, extractSetCookies(locRes.headers));
          if (locRes.status === 200) {
            const json = locRes.json();
            const grantId = getGrantId(locRes.body);
            const newCsrf = getCsrfFromJson(json) || handled.csrf;
            return { success: true, grantId, cookies: handled.cookies, csrf: newCsrf, error: null };
          }
          return { success: false, grantId: null, cookies: handled.cookies, csrf: handled.csrf, error: `challenge location retry status ${locRes.status}` };
        }
        return { success: false, grantId: null, cookies: handled.cookies, csrf: handled.csrf, error: 'no location in challenge retry' };
      }
      return { success: false, grantId: null, cookies: handled.cookies, csrf: handled.csrf, error: `challenge retry status ${retryRes.status}` };
    }
    return { success: false, grantId: null, cookies, csrf, error: handled.error };
  }
  return { success: false, grantId: null, cookies, csrf, error: `challenge status ${res.status}` };
}

function getGrantIdViaChallenge(cookies, csrf, profile) {
  const formResult = getChallengeForm(cookies, csrf, profile);
  if (!formResult.success) {
    return { success: false, grantId: null, cookies, csrf, error: formResult.error };
  }
  cookies = formResult.cookies;
  csrf = formResult.csrf;
  const action = getChallengeAction(formResult.html);
  const challengeValue = getChallengeInput(formResult.html);
  if (!action || !challengeValue) {
    return { success: false, grantId: null, cookies, csrf, error: 'no challenge action or input' };
  }
  const postResult = postChallenge(cookies, csrf, action, challengeValue, profile);
  if (!postResult.success) {
    return { success: false, grantId: null, cookies, csrf, error: postResult.error };
  }
  return { success: true, grantId: postResult.grantId, cookies: postResult.cookies, csrf: postResult.csrf, error: null };
}

