    const statusUrl = getStatusUrl(json);
    return { success: true, statusUrl, cookies, csrf: newCsrf, error: null };
  }
  if (res.status === 401) {
    const handled = handle401(res, cookies, csrf, cartId, 'reservation');
    if (handled.retry) {
      const retryRes = makeRequest('POST', `${BASE_URL}/v2/reservations`, body, headers, handled.cookies, 0);
      if (retryRes.status === 202) {
        mergeCookies(handled.cookies, extractSetCookies(retryRes.headers));
        const json = retryRes.json();
        const newCsrf = getCsrfFromJson(json) || handled.csrf;
        const statusUrl = getStatusUrl(json);
        return { success: true, statusUrl, cookies: handled.cookies, csrf: newCsrf, error: null };
      }
      return { success: false, statusUrl: null, cookies: handled.cookies, csrf: handled.csrf, error: `reservation retry status ${retryRes.status}` };
    }
    return { success: false, statusUrl: null, cookies, csrf, error: handled.error };
  }
