function pollReservation(cookies, csrf, statusUrl, profile) {
  const headers = {
    'X-CSRF-Token': csrf,
  };
  let attempts = 0;
  while (attempts < 5) {
    sleep(0.05);
    const res = makeRequest('GET', `${BASE_URL}${statusUrl}`, null, headers, cookies, 0);
    if (res.status === 200) {
      mergeCookies(cookies, extractSetCookies(res.headers));
      const json = res.json();
      const newCsrf = getCsrfFromJson(json) || csrf;
      const status = getStatus(json);
      if (status === 'ready') {
        const reservationId = getReservationId(json);
        return { success: true, reservationId, cookies, csrf: newCsrf, error: null };
      }
      if (status === 'failed') {
        return { success: false, reservationId: null, cookies, csrf: newCsrf, error: 'reservation failed' };
      }
      // pending, continue
      cookies = cookies;
      csrf = newCsrf;
    } else if (res.status === 401) {
      const handled = handle401(res, cookies, csrf, null, 'poll-reservation');
      if (handled.retry) {
        cookies = handled.cookies;
        csrf = handled.csrf;
      } else {
        return { success: false, reservationId: null, cookies, csrf, error: handled.error };
      }
    } else {
      return { success: false, reservationId: null, cookies, csrf, error: `poll status ${res.status}` };
    }
    attempts++;
  }
  return { success: false, reservationId: null, cookies, csrf, error: 'reservation polling exhausted' };
}

function createOrder(cookies, csrf, cartId, reservationId, idempotencyKey, etag, profile) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    'Idempotency-Key': idempotencyKey,
  };
  if (etag) {
    headers['If-Match'] = etag;
  }
  const body = {
    cart_id: cartId,
  };
  if (reservationId) {
    body.reservation_id = reservationId;
  }
  const res = makeRequest('POST', `${BASE_URL}/v2/orders`, JSON.stringify(body), headers, cookies, 0);
  if (res.status === 201) {
    mergeCookies(cookies, extractSetCookies(res.headers));
    const json = res.json();
    const newCsrf = getCsrfFromJson(json) || csrf;
    const accepted = getAccepted(json);
    const orderId = getOrderId(json);
    if (accepted === true) {
      return { success: true, accepted: true, orderId, cookies, csrf: newCsrf, error: null };
    }
    return { success: false, accepted: false, orderId, cookies, csrf: newCsrf, error: 'order not accepted' };
  }
  if (res.status === 200) {
    mergeCookies(cookies, extractSetCookies(res.headers));
    const json = res.json();
    const newCsrf = getCsrfFromJson(json) || csrf;
    const accepted = getAccepted(json);
    const orderId = getOrderId(json);
    if (accepted === true) {
      return { success: true, accepted: true, orderId, cookies, csrf: newCsrf, error: null };
    }
    return { success: false, accepted: false, orderId, cookies, csrf: newCsrf, error: 'order not accepted (200)' };
  }
  if (res.status === 401) {
    const handled = handle401(res, cookies, csrf, cartId, 'order');
    if (handled.retry) {
      const retryHeaders = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': handled.csrf,
        'Idempotency-Key': idempotencyKey,
      };
      if (etag) {
        retryHeaders['If-Match'] = etag;
      }
      const retryRes = makeRequest('POST', `${BASE_URL}/v2/orders`, JSON.stringify(body), retryHeaders, handled.cookies, 0);
      if (retryRes.status === 201 || retryRes.status === 200) {
        mergeCookies(handled.cookies, extractSetCookies(retryRes.headers));
        const json = retryRes.json();
        const newCsrf = getCsrfFromJson(json) || handled.csrf;
        const accepted = getAccepted(json);
        const orderId = getOrderId(json);
        if (accepted === true) {
          return { success: true, accepted: true, orderId, cookies: handled.cookies, csrf: newCsrf, error: null };
        }
        return { success: false, accepted: false, orderId, cookies: handled.cookies, csrf: newCsrf, error: 'order retry not accepted' };
      }
      return { success: false, accepted: false, orderId: null, cookies: handled.cookies, csrf: handled.csrf, error: `order retry status ${retryRes.status}` };
    }
    return { success: false, accepted: false, orderId: null, cookies, csrf, error: handled.error };
  }
  return { success: false, accepted: false, orderId: null, cookies, csrf, error: `order status ${res.status}` };
}

function doWork(cookies, csrf, profile) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };
  let attempts = 0;
  while (attempts < 5) {
    const res = makeRequest('POST', `${BASE_URL}/v2/work`, '{}', headers, cookies, 0);
    if (res.status === 200) {
