      if (!recoverResult.success) {
        return { success: false, response: recoverResult.response, recovered: false };
      }
    }
    // Retry the operation once
    const retryResult = operationFn(state, ...operationArgs);
    return { success: retryResult.success, response: retryResult.response, recovered: true, retryResult: retryResult };
  }

  // Renew failed, try fresh login
  const loginResult = freshLogin(state);
  if (!loginResult.success) {
    return { success: false, response: loginResult.response, recovered: false };
  }
  if (cartId) {
    const recoverResult = recoverCart(state, cartId);
    if (!recoverResult.success) {
      return { success: false, response: recoverResult.response, recovered: false };
    }
