  let cartResult = createCart(state, product.id, variantId);
  if (!cartResult.success) {
    if (isExpired(cartResult.response)) {
      const recoveryResult = handleExpiry(state, null, createCart, [product.id, variantId]);
      if (recoveryResult.success && recoveryResult.retryResult) {
        cartResult = recoveryResult.retryResult;
      } else {
        results.errors.push('cart_create_expiry_recovery_failed');
        return results;
      }
    } else {
      results.errors.push('cart_create_failed');
      return results;
    }
  }
  results.cartCreated = true;
  results.cartId = cartResult.cartId;
  let cartEtag = cartResult.etag;

