      const reReadResult = getCart(state, cartResult.cartId);
      if (reReadResult.success) {
        cartEtag = reReadResult.etag;
        patchResult = patchCart(state, cartResult.cartId, quantity, cartEtag);
      }
    }
    if (!patchResult.success) {
      if (isExpired(patchResult.response)) {
        const recoveryResult = handleExpiry(state, cartResult.cartId, patchCart, [cartResult.cartId, quantity, cartEtag]);
        if (recoveryResult.success && recoveryResult.retryResult) {
          patchResult = recoveryResult.retryResult;
          if (patchResult.etag) cartEtag = patchResult.etag;
        } else {
          results.errors.push('patch_expiry_recovery_failed');
          return results;
        }
      } else {
        results.errors.push('patch_failed');
        return results;
      }
    }
  }
  if (patchResult.etag) cartEtag = patchResult.etag;

  // Create reservation
  let reservationResult = createReservation(state, cartResult.cartId);
  if (!reservationResult.success) {
    if (isExpired(reservationResult.response)) {
      const recoveryResult = handleExpiry(state, cartResult.cartId, createReservation, [cartResult.cartId]);
      if (recoveryResult.success && recoveryResult.retryResult) {
        reservationResult = recoveryResult.retryResult;
      } else {
        results.errors.push('reservation_expiry_recovery_failed');
        return results;
      }
    } else {
      results.errors.push('reservation_failed');
      return results;
    }
  }

