  while (pollCount < 5) {
    pollResult = pollReservation(state, reservationResult.statusUrl);
    if (!pollResult.success) {
      if (isExpired(pollResult.response)) {
        const recoveryResult = handleExpiry(state, cartResult.cartId, pollReservation, [reservationResult.statusUrl]);
        if (recoveryResult.success && recoveryResult.retryResult) {
          pollResult = recoveryResult.retryResult;
        } else {
          results.errors.push('poll_expiry_recovery_failed');
          return results;
        }
      } else {
        results.errors.push('poll_failed');
        return results;
      }
    }
    if (pollResult.status === 'ready') {
      reservationId = pollResult.reservationId;
      break;
    }
    if (pollResult.status === 'failed') {
      results.errors.push('reservation_failed_status');
      return results;
    }
    sleep(0.05);
    pollCount++;
  }

  if (!reservationId) {
    results.errors.push('reservation_not_ready');
    return results;
  }

  // Create order
  const idempotencyKey = `order-${cartResult.cartId}-${state.vuId}-${state.iteration}`;
  let orderResult = createOrder(state, cartResult.cartId, reservationId, idempotencyKey, cartEtag);
  if (!orderResult.success) {
    if (isExpired(orderResult.response)) {
