      if (recoveryResult.success && recoveryResult.retryResult) {
        orderResult = recoveryResult.retryResult;
      } else {
        results.errors.push('order_expiry_recovery_failed');
        return results;
      }
    } else {
      results.errors.push('order_failed');
      return results;
    }
  }

