  { job_polls: 2, poll_interval: 0.02 },
  { job_polls: 3, poll_interval: 0.02, html_layout: 1, reverse_catalog: true }
];

const NEGATIVE_OVERRIDES = [{ job_fails: true }];

function getProfile(userIndex) {
  const profile = PROFILES[userIndex % PROFILES.length];
  const override = NEGATIVE_OVERRIDES[userIndex % NEGATIVE_OVERRIDES.length];
  return Object.assign({}, profile, override);
}

function extractCsrf(html) {
  const match = html.match(/name="csrf"[^>]*value="([^"]+)"/);
  return match ? match[1] : null;
}

function extractLoginNonce(html) {
  const match = html.match(/name="login_nonce"[^>]*value="([^"]+)"/);
  return match ? match[1] : null;
}

function extractChallengeAction(html) {
  const match = html.match(/form action="(\/v2\/challenges\/[^"]+)"/);
  return match ? match[1] : null;
}

function extractChallengeInput(html) {
  const match = html.match(/name="challenge"[^>]*value="([^"]+)"/);
  return match ? match[1] : null;
