    fail('No CSRF token found in login form');
  }

  // Step 2: POST login
  const loginPayload = JSON.stringify({
    username: username,
    password: password,
    csrf: csrf,
  });

  const loginRes = httpClient.post(`${BASE_URL}/v2/login`, loginPayload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'login' },
  });

  let sessionCsrf = csrf;
  let sessionCookie = null;

  if (loginRes.status === 200) {
    const loginData = JSON.parse(loginRes.body);
    if (loginData.csrf) {
      sessionCsrf = loginData.csrf;
    }
    sessionCookie = loginRes.cookies;
  } else if (loginRes.status === 302) {
    const location = extractLocation(loginRes.headers);
    if (!location) {
      fail('Login 302 without Location');
    }
    const followRes = httpClient.get(location, {
      redirects: 0,
      tags: { name: 'login_follow' },
    });
    if (followRes.status === 200) {
      const followData = JSON.parse(followRes.body);
      if (followData.csrf) {
        sessionCsrf = followData.csrf;
      }
      sessionCookie = followRes.cookies;
    } else if (followRes.status === 302) {
      const loc2 = extractLocation(followRes.headers);
      if (loc2) {
        const follow2Res = httpClient.get(loc2, {
          redirects: 0,
          tags: { name: 'login_follow2' },
        });
        if (follow2Res.status === 200) {
          const follow2Data = JSON.parse(follow2Res.body);
          if (follow2Data.csrf) {
            sessionCsrf = follow2Data.csrf;
          }
          sessionCookie = follow2Res.cookies;
        }
      }
    }
  } else {
    fail(`Login failed with status ${loginRes.status}`);
  }

  return {
    csrf: sessionCsrf,
    cookies: sessionCookie,
    username: username,
  };
}

function getChallengeForm(httpClient, csrf) {
