  }

  const html = res.body;
  const action = extractChallengeAction(html);
  const challengeValue = extractChallengeInput(html);

  if (!action || !challengeValue) {
    return { error: 'challenge_form_missing_fields', status: res.status };
  }

  return {
    action: action,
    challenge: challengeValue,
    status: res.status,
  };
}

function submitChallenge(httpClient, action, challengeValue, csrf) {
  const payload = JSON.stringify({ challenge: challengeValue });
  const res = httpClient.post(action, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'challenge_submit' },
  });

  if (res.status === 302) {
    const location = extractLocation(res.headers);
    if (!location) {
      return { error: 'challenge_302_no_location', status: res.status };
    }
    const followRes = httpClient.get(location, {
      headers: {
        'X-CSRF-Token': csrf,
      },
      redirects: 0,
      tags: { name: 'challenge_follow' },
    });
    if (followRes.status === 200) {
      const grantId = extractGrantIdFromJson(followRes.body);
      const newCsrf = extractCsrfFromJson(followRes.body);
      return {
        grant_id: grantId,
        csrf: newCsrf || csrf,
        status: followRes.status,
      };
    } else if (followRes.status === 302) {
      const loc2 = extractLocation(followRes.headers);
      if (loc2) {
        const follow2Res = httpClient.get(loc2, {
          headers: {
            'X-CSRF-Token': csrf,
          },
          redirects: 0,
          tags: { name: 'challenge_follow2' },
        });
        if (follow2Res.status === 200) {
          const grantId = extractGrantIdFromJson(follow2Res.body);
          const newCsrf = extractCsrfFromJson(follow2Res.body);
          return {
            grant_id: grantId,
            csrf: newCsrf || csrf,
            status: follow2Res.status,
          };
        }
      }
    }
    return { error: 'challenge_follow_failed', status: followRes.status };
  } else if (res.status === 200) {
    const grantId = extractGrantIdFromJson(res.body);
    const newCsrf = extractCsrfFromJson(res.body);
    return {
      grant_id: grantId,
      csrf: newCsrf || csrf,
      status: res.status,
    };
  } else {
    return { error: `challenge_submit_status_${res.status}`, status: res.status };
  }
}

