function patchCart(httpClient, csrf, cartId, etag, quantity) {
  const payload = JSON.stringify({ quantity: quantity });
  const res = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
    },
    redirects: 0,
    tags: { name: 'patch_cart' },
  });

  if (res.status === 200 || res.status === 204) {
    const newCsrf = extractCsrfFromJson(res.body);
    const newEtag = extractETag(res.headers);
    return {
      csrf: newCsrf || csrf,
      etag: newEtag || etag,
      status: res.status,
    };
  } else if (res.status === 412) {
    // Re-read and retry once
    const reRead = getCart(httpClient, csrf, cartId);
    if (reRead.error) {
      return { error: 'patch_412_reread_failed', status: res.status };
    }
    const retryRes = httpClient.patch(`${BASE_URL}/v2/carts/${cartId}`, payload, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': reRead.csrf,
        'If-Match': reRead.etag,
      },
      redirects: 0,
      tags: { name: 'patch_cart_retry' },
    });
    if (retryRes.status === 200 || retryRes.status === 204) {
      const newCsrf = extractCsrfFromJson(retryRes.body);
      const newEtag = extractETag(retryRes.headers);
      return {
        csrf: newCsrf || reRead.csrf,
        etag: newEtag || reRead.etag,
        status: retryRes.status,
      };
    } else {
      return { error: `patch_cart_retry_status_${retryRes.status}`, status: retryRes.status };
    }
  } else {
    return { error: `patch_cart_status_${res.status}`, status: res.status };
  }
}

