function pollReservation(httpClient, csrf, statusUrl) {
  let reservationId = null;
  let finalStatus = null;

  for (let i = 0; i < 5; i++) {
    if (i > 0) {
      sleep(0.06);
    }
    const fullUrl = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
    const res = httpClient.get(fullUrl, {
      headers: {
        'X-CSRF-Token': csrf,
      },
      redirects: 0,
      tags: { name: 'poll_reservation' },
    });

    if (res.status === 200) {
      const status = extractStatus(res.body);
      const newCsrf = extractCsrfFromJson(res.body);
      if (newCsrf) csrf = newCsrf;
      if (status === 'ready') {
        reservationId = extractReservationId(res.body);
        finalStatus = 'ready';
        break;
      } else if (status === 'failed') {
        finalStatus = 'failed';
        break;
      } else if (status === 'pending') {
        finalStatus = 'pending';
        continue;
      } else {
        finalStatus = status;
        break;
      }
    } else {
      finalStatus = `poll_status_${res.status}`;
      break;
    }
  }

  return {
    reservation_id: reservationId,
    status: finalStatus,
    csrf: csrf,
  };
}

