function doWork(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'work' },
  });

  if (res.status === 200) {
    const newCsrf = extractCsrfFromJson(res.body);
    return {
      csrf: newCsrf || csrf,
      status: res.status,
      ok: true,
    };
  } else if (res.status === 429) {
    const retryAfter = res.headers['Retry-After'] || res.headers['retry-after'];
    const waitTime = retryAfter ? parseInt(retryAfter, 10) : 1;
    if (waitTime > 0 && waitTime <= 4) {
      sleep(waitTime);
      // Retry up to 4 times
      for (let i = 0; i < 4; i++) {
        const retryRes = httpClient.post(`${BASE_URL}/v2/work`, '{}', {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': csrf,
          },
          redirects: 0,
          tags: { name: 'work_retry' },
        });
        if (retryRes.status === 200) {
          const newCsrf = extractCsrfFromJson(retryRes.body);
          return {
            csrf: newCsrf || csrf,
            status: retryRes.status,
            ok: true,
          };
        } else if (retryRes.status === 429) {
          const ra = retryRes.headers['Retry-After'] || retryRes.headers['retry-after'];
          const wt = ra ? parseInt(ra, 10) : 1;
          if (wt > 0 && wt <= 4) {
            sleep(wt);
          } else {
            sleep(1);
          }
        } else {
          return {
            csrf: csrf,
            status: retryRes.status,
            ok: false,
          };
        }
      }
      return {
        csrf: csrf,
        status: 429,
        ok: false,
      };
    } else {
      return {
        csrf: csrf,
        status: 429,
        ok: false,
      };
    }
  } else {
    return {
      csrf: csrf,
      status: res.status,
      ok: false,
    };
  }
}

