function handleExpiredSession(httpClient, csrf, cartId, operation, operationFn) {
  // Try renew
  const renewResult = renewSession(httpClient, csrf);
  if (renewResult.error) {
    // Renew failed, try full re-login
    const loginResult = login(httpClient.vu.idInTest || 1, httpClient);
    if (loginResult.csrf) {
      csrf = loginResult.csrf;
    }
  } else {
    csrf = renewResult.csrf;
  }

  // Recover cart if exists
  if (cartId) {
    const recoverResult = recoverCart(httpClient, csrf, cartId);
    if (!recoverResult.error) {
      csrf = recoverResult.csrf;
      if (recoverResult.etag) {
        // Update etag for subsequent operations
        return {
          csrf: csrf,
          etag: recoverResult.etag,
          recovered: true,
        };
      }
    }
  }

  // Retry the interrupted operation once
  const retryResult = operationFn(httpClient, csrf);
  return {
    csrf: retryResult.csrf || csrf,
    etag: retryResult.etag,
    result: retryResult,
    recovered: true,
  };
}

function handleSessionError(httpClient, csrf, cartId, errorType, operationFn) {
  if (errorType === 'expired') {
    return handleExpiredSession(httpClient, csrf, cartId, 'expired', operationFn);
  } else if (errorType === 'session') {
    // Session revoked: get fresh form/login, recover cart
    const loginResult = login(httpClient.vu.idInTest || 1, httpClient);
    if (!loginResult.csrf) {
      return { error: 'relogin_failed', csrf: csrf };
    }
    csrf = loginResult.csrf;
    if (cartId) {
      const recoverResult = recoverCart(httpClient, csrf, cartId);
      if (!recoverResult.error) {
        csrf = recoverResult.csrf;
      }
    }
    const retryResult = operationFn(httpClient, csrf);
    return {
      csrf: retryResult.csrf || csrf,
      etag: retryResult.etag,
      result: retryResult,
      recovered: true,
    };
  } else if (errorType === 'denied') {
    // Not expiry: fail assertion
    return { error: 'denied_not_expiry', csrf: csrf };
  } else {
    return { error: `unknown_error_${errorType}`, csrf: csrf };
  }
}

function extractErrorFromResponse(res) {
  const error = extractError(res.body);
  if (error) return error;
  if (res.status === 401) {
    return 'unauthorized';
  }
  return null;
}

function performJourney(vuId, iteration) {
  const profile = getProfile(vuId);
  const httpClient = http;

  // Fresh login
  const loginResult = login(vuId, httpClient);
  let csrf = loginResult.csrf;
  let cartId = null;
  let cartEtag = null;
  let grantId = null;
  let reservationId = null;
  let orderPlaced = false;
  let idempotencyKey = `idem-${vuId}-${iteration}-${Date.now()}`;

  // Track business responses for failure rate
  let businessResponses = 0;
  let businessFailures = 0;

  // Step 1: Get challenge form
  const challengeFormResult = getChallengeForm(httpClient, csrf);
  if (challengeFormResult.error) {
    challengeSuccess.add(false);
    businessResponses++;
    businessFailures++;
    businessFailure.add(1);
    return;
  }

  // Step 2: Submit challenge
  const challengeResult = submitChallenge(
    httpClient,
    challengeFormResult.action,
    challengeFormResult.challenge,
    csrf
  );

  if (challengeResult.error) {
    challengeSuccess.add(false);
    businessResponses++;
    businessFailures++;
    businessFailure.add(1);
    return;
  }

  if (challengeResult.csrf) {
    csrf = challengeResult.csrf;
  }
  grantId = challengeResult.grant_id;

  if (!grantId) {
    challengeSuccess.add(false);
    businessResponses++;
    businessFailures++;
    businessFailure.add(1);
    return;
  }

  challengeSuccess.add(true);

  // Step 3: Get catalog
  const catalogResult = getCatalog(httpClient, csrf, profile.reverse_catalog || false);
  if (catalogResult.error) {
    businessResponses++;
    businessFailures++;
    businessFailure.add(1);
    return;
  }

  let products = catalogResult.products;
  let nextUrl = catalogResult.next;

  // Traverse at most 3 pages
  let pagesTraversed = 0;
  while (nextUrl && pagesTraversed < 3) {
    const pageResult = getCatalogPage(httpClient, csrf, nextUrl);
    if (pageResult.error) {
      businessResponses++;
      businessFailures++;
      businessFailure.add(1);
      break;
    }
    if (pageResult.product) {
      products.push(pageResult.product);
    }
    nextUrl = pageResult.next;
    pagesTraversed++;
  }

  if (products.length === 0) {
    businessResponses++;
    businessFailures++;
    businessFailure.add(1);
    return;
  }

  // Select first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;
  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    businessResponses++;
    businessFailures++;
    businessFailure.add(1);
    return;
  }

  // Step 4: Create cart with grant_id
  const createCartResult = createCart(
    httpClient,
    csrf,
    selectedProduct.id,
    selectedVariant.id,
    grantId
  );

  if (createCartResult.error) {
    businessResponses++;
    businessFailures++;
    businessFailure.add(1);
    return;
  }

  cartId = createCartResult.cart_id;
  cartEtag = createCartResult.etag;
  if (createCartResult.csrf) {
