      try {
        const json = res.json();
        if (json.ok === true) {
          return { success: true };
        }
      } catch (e) {
        // fall through
      }
      businessFailures.add(1);
      return { success: false, error: 'browse not ok' };
    }

    if (res.status === 429) {
      const retryAfter = getRetryAfter(res.headers);
      sleep(retryAfter);
      attempts++;
      continue;
    }

    if (res.status === 401) {
      if (isExpired401(res)) {
        return { success: false, expired: true };
      }
      if (isSessionRevoked401(res)) {
        return { success: false, revoked: true };
      }
      if (isDenied401(res)) {
        businessFailures.add(1);
        return { success: false, denied: true };
      }
    }

    businessFailures.add(1);
    return { success: false, error: `browse status ${res.status}` };
  }

  businessFailures.add(1);
  return { success: false, error: 'browse retries exhausted' };
}

// Helper: full journey with recovery
function executeJourney(username, password, delayMs, threadId, reverseCatalog) {
  // Apply per-thread CSV delay to stagger subsequent work
  if (delayMs > 0) {
    sleep(delayMs / 1000);
  }

  // Step 1: Login
  let loginResult = performLogin(username, password);
  if (!loginResult.success) {
    fail(`Login failed: ${loginResult.error}`);
  }

  let csrf = loginResult.csrf;
  let cartId = null;
  let cartEtag = null;
  let orderIdempotencyKey = null;
  let reservationId = null;
  let grantId = null;
  let orderCommittedThisJourney = false;
  let recoveryAttempted = false;
  let revocationDetectedThisJourney = false;

  // Step 2: Get catalog
  const catalogResult = getCatalog();
  if (!catalogResult.success) {
    fail(`Catalog failed: ${catalogResult.error}`);
  }

  let products = catalogResult.json.data.products;
  let nextCursor = extractNextFromCatalog(catalogResult.json);

  // Traverse at most 3 pages
  let pagesTraversed = 0;
  while (nextCursor && pagesTraversed < 3) {
    const pageResult = getCatalogPage(nextCursor);
    if (!pageResult.success) {
      break;
    }
    const pageProduct = extractProductFromPage(pageResult.json);
    if (pageProduct) {
      products.push(pageProduct);
    }
    nextCursor = extractNextFromCatalog(pageResult.json);
    pagesTraversed++;
  }

  if (products.length === 0) {
    fail('No products found in catalog');
  }

  // Select product (reverse catalog if profile requires)
  let selectedProduct = null;
  if (reverseCatalog) {
    selectedProduct = products[products.length - 1];
  } else {
    selectedProduct = products[0];
  }

  const selectedVariant = extractVariant(selectedProduct);
  if (!selectedVariant) {
    fail('No variant found for selected product');
  }

  // Step 3: Get challenge form and complete challenge
  const challengeFormResult = getChallengeForm(csrf);
  if (challengeFormResult.success) {
    const challengeResult = postChallenge(challengeFormResult.action, 'bench', csrf);
    if (challengeResult.success) {
      grantId = challengeResult.grantId;
      csrf = challengeResult.csrf;
    }
  }

  // Step 4: Create cart
  const createCartResult = createCart(selectedProduct.id, selectedVariant.id, grantId, csrf);
  if (!createCartResult.success) {
    // Check if 401 expired
    if (createCartResult.status === 401) {
      // Need to check the actual response
      // We'll handle this in the main flow
    }
    fail(`Cart creation failed: ${createCartResult.error || createCartResult.status}`);
  }

  cartId = createCartResult.cartId;
  csrf = createCartResult.csrf;
  cartEtag = createCartResult.etag;
  orderIdempotencyKey = `order-${cartId}-${threadId}-${Date.now()}`;

  // Step 5: Patch cart quantity
  const patchResult = patchCart(cartId, 1, cartEtag, csrf);
  if (patchResult.success) {
    csrf = patchResult.csrf;
    cartEtag = patchResult.etag;
  } else if (patchResult.status === 412) {
    // Re-read and retry once
    const getCartResult = getCart(cartId, csrf);
    if (getCartResult.success) {
      cartEtag = getCartResult.etag;
      const retryPatch = patchCart(cartId, 1, cartEtag, csrf);
      if (retryPatch.success) {
        csrf = retryPatch.csrf;
        cartEtag = retryPatch.etag;
      } else if (retryPatch.status === 401) {
        // Handle 401 in main flow
      } else {
        fail(`Cart patch retry failed: ${retryPatch.status}`);
      }
    }
  } else if (patchResult.status === 401) {
    // Handle 401 in main flow
  } else {
    fail(`Cart patch failed: ${patchResult.status}`);
  }

  // Step 6: Create reservation
  const reservationResult = createReservation(cartId, csrf);
  if (reservationResult.success) {
    csrf = reservationResult.csrf;
    const pollResult = pollReservation(reservationResult.statusUrl, csrf);
    if (pollResult.success) {
      reservationId = pollResult.reservationId;
      csrf = pollResult.csrf;
    }
  }

  // Step 7: Create order
  const orderResult = createOrder(cartId, reservationId, orderIdempotencyKey, cartEtag, csrf);
  if (orderResult.success && orderResult.accepted) {
    orderCommittedThisJourney = true;
    csrf = orderResult.csrf;
  } else if (orderResult.status === 401) {
    // Handle 401 in main flow
  } else if (orderResult.accepted === false) {
    fail('Order not accepted (business failure)');
  } else {
    fail(`Order creation failed: ${orderResult.error || orderResult.status}`);
  }

  // Step 8: Perform work
  const workResult = performWork(csrf);
  if (workResult.success) {
    // Work succeeded
  } else if (workResult.expired) {
    // Session expired - renew
    const renewResult = renewSession(csrf);
    if (renewResult.success) {
      csrf = renewResult.csrf;
      // Recover cart if exists
      if (cartId) {
        const recoverResult = recoverCart(cartId, csrf);
        if (recoverResult.success) {
          csrf = recoverResult.csrf;
          cartEtag = recoverResult.etag;
          recoverySucceeded.add(1);
        }
      }
      // Retry work once
      const retryWork = performWork(csrf);
      if (!retryWork.success) {
        fail(`Work retry after renew failed: ${retryWork.error || 'unknown'}`);
      }
    } else {
      fail('Session renew failed');
    }
  } else if (workResult.revoked) {
    revocationDetected.add(1);
    revocationDetectedThisJourney = true;
    // Session revoked - get fresh login
    const freshLogin = performLogin(username, password);
    if (freshLogin.success) {
      csrf = freshLogin.csrf;
      // Recover cart
      if (cartId) {
        const recoverResult = recoverCart(cartId, csrf);
        if (recoverResult.success) {
          csrf = recoverResult.csrf;
          cartEtag = recoverResult.etag;
          recoverySucceeded.add(1);
          recoveryAttempted = true;
        }
      }
      // Retry work once
      const retryWork = performWork(csrf);
      if (!retryWork.success) {
        fail(`Work retry after revocation recovery failed: ${retryWork.error || 'unknown'}`);
      }
    } else {
      fail('Fresh login after revocation failed');
    }
  } else if (workResult.denied) {
    fail('Work denied (unexpected)');
  } else {
    fail(`Work failed: ${workResult.error}`);
  }

  // Step 9: Perform browse
  const browseResult = performBrowse(csrf);
  if (browseResult.success) {
    // Browse succeeded
  } else if (browseResult.expired) {
    const renewResult = renewSession(csrf);
    if (renewResult.success) {
      csrf = renewResult.csrf;
      if (cartId) {
        const recoverResult = recoverCart(cartId, csrf);
        if (recoverResult.success) {
          csrf = recoverResult.csrf;
          cartEtag = recoverResult.etag;
          recoverySucceeded.add(1);
        }
      }
      const retryBrowse = performBrowse(csrf);
      if (!retryBrowse.success) {
        fail(`Browse retry after renew failed: ${retryBrowse.error || 'unknown'}`);
      }
    } else {
      fail('Session renew failed for browse');
    }
  } else if (browseResult.revoked) {
    revocationDetected.add(1);
    revocationDetectedThisJourney = true;
    const freshLogin = performLogin(username, password);
    if (freshLogin.success) {
      csrf = freshLogin.csrf;
      if (cartId) {
        const recoverResult = recoverCart(cartId, csrf);
        if (recoverResult.success) {
          csrf = recoverResult.csrf;
          cartEtag = recoverResult.etag;
          recoverySucceeded.add(1);
          recoveryAttempted = true;
        }
      }
      const retryBrowse = performBrowse(csrf);
      if (!retryBrowse.success) {
        fail(`Browse retry after revocation recovery failed: ${retryBrowse.error || 'unknown'}`);
      }
    } else {
      fail('Fresh login after revocation failed for browse');
    }
  } else if (browseResult.denied) {
    fail('Browse denied (unexpected)');
  } else {
    fail(`Browse failed: ${browseResult.error}`);
  }

  // Verify order was committed
  if (!orderCommittedThisJourney) {
    fail('Order was not committed in this journey');
  }

  return {
    orderCommitted: orderCommittedThisJourney,
    revocationDetected: revocationDetectedThisJourney,
    recoveryAttempted: recoveryAttempted
  };
}

