function extractCsrfFromHtml(html) {
  const regex = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/;
  const match = html.match(regex);
  return match ? match[1] : null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  return loc || null;
}

function extractETag(headers) {
  const etag = headers['ETag'];
  return etag || null;
}

function extractError(body) {
  const match = body.match(/"error"\s*:\s*"(expired|session)"/);
  return match ? match[1] : null;
}

function renewSession(httpClient, csrf) {
  const renewRes = httpClient.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (renewRes.status === 200) {
    try {
      const renewBody = renewRes.json();
      if (renewBody.csrf) {
        return { csrf: renewBody.csrf, renewed: true };
      }
    } catch (e) {
      // ignore
    }
  }
  return { csrf, renewed: false };
}

function recoverCart(httpClient, csrf, cartId) {
  if (!cartId || cartId === 'MISSING') return csrf;
  const recoverRes = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (recoverRes.status === 200) {
    try {
      const recoverBody = recoverRes.json();
      if (recoverBody.csrf) {
        return recoverBody.csrf;
      }
    } catch (e) {
      // ignore
    }
  }
  return csrf;
}

function freshLogin(httpClient, username) {
  const formRes = httpClient.get(`${BASE_URL}/v2/login-form`);
  const formCsrf = extractCsrfFromHtml(formRes.body);
  if (!formCsrf) {
    throw new Error('Failed to extract login csrf');
  }
  const loginRes = httpClient.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: 'bench',
    csrf: formCsrf,
  }), {
    headers: {
      'Content-Type': 'application/json',
    },
  });
  let csrf = formCsrf;
  if (loginRes.status === 200) {
    try {
      const loginBody = loginRes.json();
      if (loginBody.csrf) {
        csrf = loginBody.csrf;
      }
    } catch (e) {
      // ignore
    }
  }
  const location = extractLocation(loginRes.headers);
  if (location) {
    const redirectRes = httpClient.get(location.startsWith('http') ? location : `${BASE_URL}${location}`);
    if (redirectRes.status === 200) {
      try {
        const redirectBody = redirectRes.json();
        if (redirectBody.csrf) {
          csrf = redirectBody.csrf;
        }
      } catch (e) {
        // ignore
      }
    }
  }
  return csrf;
}

function handleExpiry(httpClient, csrf, cartId, operationFn) {
  let currentCsrf = csrf;
  let retried = false;
  const attempt = () => {
    const result = operationFn(currentCsrf);
    if (result.status === 401) {
      const errorType = extractError(result.body);
      if (errorType === 'expired') {
        const renewResult = renewSession(httpClient, currentCsrf);
        currentCsrf = renewResult.csrf;
        if (renewResult.renewed && cartId && cartId !== 'MISSING') {
          currentCsrf = recoverCart(httpClient, currentCsrf, cartId);
        }
        if (!retried) {
          retried = true;
          return attempt();
        }
      } else if (errorType === 'session') {
        currentCsrf = freshLogin(httpClient, `bench-${__VU}`);
        if (cartId && cartId !== 'MISSING') {
          currentCsrf = recoverCart(httpClient, currentCsrf, cartId);
        }
        if (!retried) {
          retried = true;
          return attempt();
        }
      }
    }
    return result;
  };
  return attempt();
}

