import http from 'k6/http';
import { check, sleep } from 'k6';
import { URL } from 'https://jslib.k6.io/url/1.0.0/index.js';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    redirect: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
  thresholds: {},
};

function extractJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function extractHeader(res, name) {
  return res.headers[name] || null;
}

function extractCsrfFromHtml(html) {
  const patterns = [
    /<input[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i,
    /<input[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']csrf["'][^>]*>/i,
  ];
  for (const p of patterns) {
    const m = html.match(p);
    if (m) return m[1];
  }
  return null;
}

function extractLocation(res) {
  return extractHeader(res, 'Location');
}

function extractETag(res) {
  return extractHeader(res, 'ETag');
}

function hasError(res, errorType) {
  const body = res.body || '';
  const re = new RegExp(`"error"\\s*:\\s*"${errorType}"`);
  return re.test(body);
}

function isExpiredOrSession(res) {
  return hasError(res, 'expired') || hasError(res, 'session');
}

function isDenied(res) {
  return hasError(res, 'denied');
}

function getLoginForm(state) {
  const res = http.get(`${BASE_URL}/v2/login-form`, {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  const csrf = extractCsrfFromHtml(res.body || '');
  if (csrf) state.csrf = csrf;
  return res;
}

function postLogin(state, username) {
  const payload = JSON.stringify({
    username: username,
    password: 'bench',
    csrf: state.csrf,
  });
  const res = http.post(`${BASE_URL}/v2/login`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });

  const json = extractJson(res);
  if (json && json.csrf) state.csrf = json.csrf;

  const location = extractLocation(res);
  if (location) {
    state.redirectLocation = location;
    state.hasRedirect = true;
  } else {
    state.hasRedirect = false;
  }

  return res;
}

function getRedirectLocation(state) {
  if (!state.hasRedirect || !state.redirectLocation) return null;
  const url = new URL(state.redirectLocation, BASE_URL);
  const path = url.pathname + (url.search || '');
  const res = http.get(`${BASE_URL}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  const json = extractJson(res);
  if (json) {
    if (json.csrf) state.csrf = json.csrf;
    if (json.grant_id) state.grant = json.grant_id;
  }
  return res;
}

function getCatalog(state) {
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  const json = extractJson(res);
  if (json && json.data && json.data.products) {
    for (const product of json.data.products) {
      if (product.variants && product.variants.length > 0 && product.variants[0].in_stock) {
        state.product = product.id;
        state.variant = product.variants[0].id;
        break;
      }
    }
  }
  return res;
}

function createCart(state) {
  const payload = JSON.stringify({
    product_id: state.product,
    variant_id: state.variant,
    grant_id: state.grant,
  });
  const res = http.post(`${BASE_URL}/v2/carts`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    redirects: 0,
  });
  const json = extractJson(res);
  if (json) {
    if (json.csrf) state.csrf = json.csrf;
    if (json.id) {
      state.cart = json.id;
      state.hasCart = true;
    }
  }
  const etag = extractETag(res);
  if (etag) state.etag = etag;
  return res;
}

function createOrder(state) {
  const payload = JSON.stringify({ cart_id: state.cart });
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf,
    'Idempotency-Key': state.cart,
  };
  if (state.etag && state.etag !== 'MISSING') {
    headers['If-Match'] = state.etag;
  }
  const res = http.post(`${BASE_URL}/v2/orders`, payload, {
    headers: headers,
    redirects: 0,
  });
  const json = extractJson(res);
  if (json && json.csrf) state.csrf = json.csrf;
  return res;
}

export default function () {
  const vuId = __VU;
  const username = `bench-${vuId}`;

  const state = {
    csrf: 'MISSING',
    cart: 'MISSING',
    etag: 'MISSING',
    hasCart: false,
    grant: 'MISSING',
    product: 'MISSING',
    variant: 'MISSING',
    redirectLocation: null,
    hasRedirect: false,
  };

  // Fresh login form
  getLoginForm(state);

  // Login (may return 302 with Location)
  const loginRes = postLogin(state, username);

  // Follow dynamic redirect Location exactly once if present
  if (state.hasRedirect && state.redirectLocation) {
    getRedirectLocation(state);
  }

  // Catalog
  getCatalog(state);

  // Create cart with grant_id
  createCart(state);

  // Create order
  createOrder(state);

  sleep(0.1);
}
