  // POST /v2/login
  res = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password, csrf: formCsrf || csrf }),
    { headers: makeHeaders(csrf, etag, cart), redirects: 0 }
  );
  check(res, { 'login status 200 or 302': (r) => r.status === 200 || r.status === 302 });

  let json = getJson(res);
  if (json && json.csrf) csrf = json.csrf;

  let location = getLocation(res);
  if (location) {
    res = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
      headers: makeHeaders(csrf, etag, cart),
      redirects: 0,
    });
    json = getJson(res);
    if (json && json.csrf) csrf = json.csrf;
    if (json && json.grant_id) grant = json.grant_id;
  }

