  res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: makeHeaders(csrf, etag, cart),
    redirects: 0,
  });
  check(res, { 'catalog status 200': (r) => r.status === 200 });
  json = getJson(res);
  if (json && json.csrf) csrf = json.csrf;

  let product = null;
  let variant = null;
  if (json && json.data && json.data.products) {
    for (const p of json.data.products) {
      if (p.variants && p.variants.length > 0 && p.variants[0].in_stock) {
        product = p.id;
        variant = p.variants[0].id;
        break;
      }
