      res = http.get(`${BASE_URL}${next}`, {
        headers: makeHeaders(csrf, etag, cart),
        redirects: 0,
      });
      json = getJson(res);
      if (json && json.csrf) csrf = json.csrf;
      if (json && json.data && json.data.products) {
        for (const p of json.data.products) {
          if (p.variants && p.variants.length > 0 && p.variants[0].in_stock) {
            product = p.id;
            variant = p.variants[0].id;
            break;
          }
        }
      }
      next = json && json.next ? json.next : null;
      if (!next) break;
    }
  }

  if (!product || !variant) {
    throw new Error('No in-stock product found');
  }

  // POST /v2/carts
  const cartBody = { product_id: product, variant_id: variant };
  if (grant && grant !== 'MISSING') cartBody.grant_id = grant;
  res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(cartBody), {
    headers: makeHeaders(csrf, etag, cart),
    redirects: 0,
  });
  check(res, { 'cart creation status 201': (r) => r.status === 201 });
  json = getJson(res);
  if (json && json.csrf) csrf = json.csrf;
  if (json && json.id) {
    cart = json.id;
    hasCart = true;
  }
  etag = getEtag(res) || etag;

  // PATCH /v2/carts/{cart}
  const quantity = accounts[__VU - 1] ? accounts[__VU - 1].quantity : 2;
