  );
  check(res, { 'patch cart status 200': (r) => r.status === 200 });
  json = getJson(res);
  if (json && json.csrf) csrf = json.csrf;
  etag = getEtag(res) || etag;

  // POST /v2/orders
  res = http.post(
    `${BASE_URL}/v2/orders`,
    JSON.stringify({ cart_id: cart }),
    { headers: makeHeaders(csrf, etag, cart), redirects: 0 }
  );
  check(res, { 'order status 201': (r) => r.status === 201 });
  json = getJson(res);
  if (json && json.csrf) csrf = json.csrf;
  check(json, { 'order accepted true': (j) => j && j.accepted === true });

  return { cart, quantity, orderAccepted: json && json.accepted === true };
}

export default function () {
  const vuIndex = __VU - 1;
  const account = accounts[vuIndex % accounts.length];
  const profile = profiles[vuIndex % profiles.length];

  if (profile.reverse_catalog) {
    // Profile with reverse_catalog: still use same flow, catalog order may differ server-side
  }

  const result = loginJourney(account.username, account.password);

  if (account.delay > 0) {
    sleep(account.delay / 1000);
  }

  // Record fresh owner seeds after execution
  console.log(`VU ${__VU} iteration ${__ITER}: cart=${result.cart}, quantity=${result.quantity}, accepted=${result.orderAccepted}`);
}
