function extractCsrf(body) {
  const m = body.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
            body.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  return m ? m[1] : null;
}

function extractJsonPath(body, path) {
  try {
    const data = JSON.parse(body);
    if (path === '$.csrf') return data.csrf || null;
    if (path === '$.grant_id') return data.grant_id || null;
    if (path === '$.id') return data.id || null;
    if (path.startsWith('$.data.products')) {
      const products = data?.data?.products || [];
      for (const p of products) {
        const v = p?.variants?.[0];
        if (v?.in_stock === true) {
          if (path.includes('.id')) return p.id;
          if (path.includes('variants[0].id')) return v.id;
        }
      }
      return null;
    }
    return null;
  } catch {
    return null;
  }
}

function getLocation(headers) {
  const loc = headers['Location'];
  return loc || null;
}

function getETag(headers) {
  const etag = headers['ETag'] || headers['Etag'] || headers['etag'];
  return etag || null;
}

function hasError(body, type) {
  try {
    const data = JSON.parse(body);
    return data?.error === type;
  } catch {
    return false;
  }
}

function renewSession(httpClient, csrf) {
  const res = httpClient.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (res.status === 200) {
    const newCsrf = extractJsonPath(res.body, '$.csrf');
    return { ok: true, csrf: newCsrf || csrf };
  }
  return { ok: false, csrf };
}

function recoverCart(httpClient, csrf, cartId) {
  if (!cartId || cartId === 'MISSING') return { ok: false, csrf };
  const res = httpClient.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (res.status === 200) {
    const newCsrf = extractJsonPath(res.body, '$.csrf');
    return { ok: true, csrf: newCsrf || csrf };
  }
  return { ok: false, csrf };
}

function freshLogin(httpClient, username) {
  const formRes = httpClient.get(`${BASE_URL}/v2/login-form`, {
    headers: { 'Content-Type': 'application/json' },
  });
  if (formRes.status !== 200) return { ok: false };

  const formCsrf = extractCsrf(formRes.body);
  if (!formCsrf) return { ok: false };

  const loginRes = httpClient.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': formCsrf,
      },
    }
  );

  if (loginRes.status === 302) {
    const loc = getLocation(loginRes.headers);
    if (loc) {
      const followRes = httpClient.get(loc.startsWith('http') ? loc : `${BASE_URL}${loc}`, {
        headers: { 'Content-Type': 'application/json' },
      });
      if (followRes.status === 200) {
        const csrf = extractJsonPath(followRes.body, '$.csrf');
        const grant = extractJsonPath(followRes.body, '$.grant_id');
        return { ok: true, csrf: csrf || formCsrf, grant: grant || 'MISSING' };
      }
      return { ok: false };
    }
    return { ok: false };
  }

  if (loginRes.status === 200) {
    const csrf = extractJsonPath(loginRes.body, '$.csrf');
    return { ok: true, csrf: csrf || formCsrf, grant: 'MISSING' };
  }

  return { ok: false };
}

function getCatalog(httpClient, csrf, profile) {
  const res = httpClient.get(`${BASE_URL}/v2/catalog`, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (res.status !== 200) return { ok: false };

  const product = extractJsonPath(res.body, '$.data.products[?(@.variants[0].in_stock == true)].id');
  const variant = extractJsonPath(res.body, '$.data.products[?(@.variants[0].in_stock == true)].variants[0].id');

  if (product && variant) {
    return { ok: true, product, variant, csrf: extractJsonPath(res.body, '$.csrf') || csrf };
  }

  // Traverse up to 3 pages
  let next = '/v2/catalog/page';
  for (let i = 0; i < 3; i++) {
    const pageRes = httpClient.get(`${BASE_URL}${next}`, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    });
    if (pageRes.status !== 200) break;

    const p = extractJsonPath(pageRes.body, '$.data.products[?(@.variants[0].in_stock == true)].id');
    const v = extractJsonPath(pageRes.body, '$.data.products[?(@.variants[0].in_stock == true)].variants[0].id');
    if (p && v) {
      return { ok: true, product: p, variant: v, csrf: extractJsonPath(pageRes.body, '$.csrf') || csrf };
    }

    try {
      const data = JSON.parse(pageRes.body);
      next = data?.next || null;
      if (!next) break;
    } catch {
      break;
    }
  }

  return { ok: false };
}

function createCart(httpClient, csrf, product, variant, grant) {
  const body = { product_id: product, variant_id: variant };
  if (grant && grant !== 'MISSING') body.grant_id = grant;

  const res = httpClient.post(`${BASE_URL}/v2/carts`, JSON.stringify(body), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });

  if (res.status === 201) {
    const cartId = extractJsonPath(res.body, '$.id');
    const newCsrf = extractJsonPath(res.body, '$.csrf');
    const etag = getETag(res.headers);
    return { ok: true, cartId, csrf: newCsrf || csrf, etag: etag || 'MISSING' };
  }

  return { ok: false };
}

function getCart(httpClient, csrf, cartId) {
  const res = httpClient.get(`${BASE_URL}/v2/carts/${cartId}`, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
  });
  if (res.status === 200) {
    const etag = getETag(res.headers);
    const newCsrf = extractJsonPath(res.body, '$.csrf');
    return { ok: true, etag: etag || 'MISSING', csrf: newCsrf || csrf };
  }
  return { ok: false };
}

function patchCart(httpClient, csrf, cartId, etag, quantity) {
  let res = httpClient.patch(
    `${BASE_URL}/v2/carts/${cartId}`,
    JSON.stringify({ quantity }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'If-Match': etag,
      },
    }
  );

  if (res.status === 412) {
    const getRes = httpClient.get(`${BASE_URL}/v2/carts/${cartId}`, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    });
    if (getRes.status === 200) {
      const newEtag = getETag(getRes.headers);
      const newCsrf = extractJsonPath(getRes.body, '$.csrf');
      res = httpClient.patch(
        `${BASE_URL}/v2/carts/${cartId}`,
        JSON.stringify({ quantity }),
        {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': newCsrf || csrf,
            'If-Match': newEtag || etag,
          },
        }
      );
      csrf = newCsrf || csrf;
      etag = newEtag || etag;
    }
  }

  if (res.status === 200) {
    const newCsrf = extractJsonPath(res.body, '$.csrf');
    const newEtag = getETag(res.headers);
    return { ok: true, csrf: newCsrf || csrf, etag: newEtag || etag };
  }

  return { ok: false };
}

function createReservation(httpClient, csrf, cartId) {
  const res = httpClient.post(
    `${BASE_URL}/v2/reservations`,
    JSON.stringify({ cart_id: cartId }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );

  if (res.status === 202) {
    const statusUrl = extractJsonPath(res.body, '$.status_url');
    const newCsrf = extractJsonPath(res.body, '$.csrf');
    return { ok: true, statusUrl, csrf: newCsrf || csrf };
  }

  return { ok: false };
}

function pollReservation(httpClient, csrf, statusUrl) {
  for (let i = 0; i < 5; i++) {
    if (i > 0) sleep(0.05);
    const res = httpClient.get(statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`, {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    });
    if (res.status === 200) {
      const status = extractJsonPath(res.body, '$.status');
      const reservationId = extractJsonPath(res.body, '$.reservation_id');
      const newCsrf = extractJsonPath(res.body, '$.csrf');
      csrf = newCsrf || csrf;
      if (status === 'ready' && reservationId) {
        return { ok: true, reservationId, csrf };
      }
      if (status === 'failed') {
        return { ok: false, csrf };
      }
    }
  }
  return { ok: false, csrf };
}

