  if (res.status === 201) {
    const accepted = extractJsonPath(res.body, '$.accepted');
    const newCsrf = extractJsonPath(res.body, '$.csrf');
    if (accepted === true) {
      return { ok: true, committed: true, csrf: newCsrf || csrf };
    }
    return { ok: false, committed: false, csrf: newCsrf || csrf };
  }

  if (res.status === 200) {
    const accepted = extractJsonPath(res.body, '$.accepted');
    const newCsrf = extractJsonPath(res.body, '$.csrf');
    if (accepted === true) {
      return { ok: true, committed: true, csrf: newCsrf || csrf };
    }
    return { ok: false, committed: false, csrf: newCsrf || csrf };
  }

  return { ok: false, committed: false, csrf };
}

function doWork(httpClient, csrf) {
  let retries = 0;
  while (retries <= 4) {
    const res = httpClient.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    });

