      const newCsrf = extractJsonPath(res.body, '$.csrf');
      return { ok: true, csrf: newCsrf || csrf };
    }

    if (res.status === 429) {
      const retryAfter = parseInt(res.headers['Retry-After'] || '1', 10) || 1;
      sleep(retryAfter);
      retries++;
      continue;
    }

    if (res.status === 500) {
      return { ok: false, csrf };
    }

    return { ok: false, csrf };
  }
  return { ok: false, csrf };
}

export function journey() {
  const vuId = __VU;
  const iterId = __ITER;
  const profile = PROFILES[(vuId + iterId) % PROFILES.length];
  const username = `bench-${((vuId - 1) % 16) + 1}`;

  const httpClient = http;

  // Fresh login
  const login = freshLogin(httpClient, username);
  if (!login.ok) {
    businessFailures.add(1);
    return;
  }
  let csrf = login.csrf;
  let grant = login.grant || 'MISSING';

  // Catalog selection
  const catalog = getCatalog(httpClient, csrf, profile);
  if (!catalog.ok) {
    businessFailures.add(1);
    return;
  }
  csrf = catalog.csrf;
  const product = catalog.product;
  const variant = catalog.variant;

  // Cart creation
  const cartCreation = createCart(httpClient, csrf, product, variant, grant);
  if (!cartCreation.ok) {
    businessFailures.add(1);
    return;
  }
  csrf = cartCreation.csrf;
  let cartId = cartCreation.cartId;
  let etag = cartCreation.etag;

  // Cart setup (PATCH quantity)
  const patch = patchCart(httpClient, csrf, cartId, etag, 2);
  if (!patch.ok) {
    businessFailures.add(1);
    return;
  }
  csrf = patch.csrf;
  etag = patch.etag;

  // Reservation
  const reservation = createReservation(httpClient, csrf, cartId);
  if (!reservation.ok) {
    businessFailures.add(1);
    return;
  }
  csrf = reservation.csrf;
  const poll = pollReservation(httpClient, csrf, reservation.statusUrl);
  if (!poll.ok) {
    businessFailures.add(1);
    return;
  }
  csrf = poll.csrf;
  const reservationId = poll.reservationId;

  // Checkout (counts as committed checkout start)
  let orderResult = postOrder(httpClient, csrf, cartId, etag, reservationId);
  csrf = orderResult.csrf;

  // Handle expiry/session recovery for order
  if (!orderResult.ok && !orderResult.committed) {
    // Check if it was an expiry error by re-reading the last response
    // We need to track the last response body; approximate by checking status
    // Since we don't have the body here, we'll attempt recovery if status was 401
    // For simplicity, we'll do a lightweight check: if the order failed, try renew+recover once
    const renew = renewSession(httpClient, csrf);
    if (renew.ok) {
      csrf = renew.csrf;
      const rec = recoverCart(httpClient, csrf, cartId);
      if (rec.ok) {
        csrf = rec.csrf;
        orderResult = postOrder(httpClient, csrf, cartId, etag, reservationId);
        csrf = orderResult.csrf;
      }
    }
  }

  if (orderResult.ok && orderResult.committed) {
    committedCheckouts.add(1);
  } else {
    businessFailures.add(1);
  }

  // Work
  const work = doWork(httpClient, csrf);
  if (!work.ok) {
    businessFailures.add(1);
  }
}
