};

function extractCsrf(body, fallback) {
  const match = body.match(/"csrf"\s*:\s*"([^"]+)"/);
  return match ? match[1] : fallback;
}

function extractGrantId(body, fallback) {
  const match = body.match(/"grant_id"\s*:\s*"([^"]+)"/);
  return match ? match[1] : fallback;
}

function extractCartId(body, fallback) {
  const match = body.match(/"id"\s*:\s*"cart-([^"]+)"/);
  return match ? `cart-${match[1]}` : fallback;
}

function extractProductAndVariant(body) {
  const productMatch = body.match(/"products"\s*:\s*\[\s*\{[^}]*"id"\s*:\s*"([^"]+)"[^}]*"variants"\s*:\s*\[\s*\{[^}]*"id"\s*:\s*"([^"]+)"[^}]*"in_stock"\s*:\s*true/);
  if (productMatch) {
    return { product: productMatch[1], variant: productMatch[2] };
  }
  return null;
}

function extractLocation(headers, fallback) {
  const location = headers['Location'];
  return location ? location : fallback;
}

function extractEtag(headers, fallback) {
  const etag = headers['ETag'];
  return etag ? etag : fallback;
}

function extractError(body) {
  const match = body.match(/"error"\s*:\s*"(expired|session|denied)"/);
  return match ? match[1] : null;
}

function renewSession(csrf) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    tags: { name: 'session-renew' },
  });
  if (renewRes.status === 200) {
    const newCsrf = extractCsrf(renewRes.body, csrf);
    return { csrf: newCsrf, ok: true };
  }
  return { csrf, ok: false };
}

function recoverCart(csrf, cartId) {
  if (!cartId || cartId === 'MISSING') return csrf;
  const recoverRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    tags: { name: 'cart-recover' },
  });
  if (recoverRes.status === 200) {
    return extractCsrf(recoverRes.body, csrf);
  }
  return csrf;
}

function freshLogin(username) {
  // GET login form
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    tags: { name: 'login-form' },
  });
  check(formRes, {
    'login-form status 200': (r) => r.status === 200,
  });

  // Extract CSRF from form (input[name=csrf])
  const formMatch = formRes.body.match(/<input[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i);
  const formCsrf = formMatch ? formMatch[1] : 'MISSING';

  // POST login
  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      tags: { name: 'login' },
    }
  );

  let csrf = extractCsrf(loginRes.body, formCsrf);
  let location = extractLocation(loginRes.headers, null);

  // Handle 302 redirect if present
  if (loginRes.status === 302 && location) {
    const redirectRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
      tags: { name: 'login-redirect' },
    });
    csrf = extractCsrf(redirectRes.body, csrf);
    const grantId = extractGrantId(redirectRes.body, 'MISSING');
    if (grantId !== 'MISSING') {
      return { csrf, grantId, cartId: 'MISSING', etag: 'MISSING', hasCart: false };
    }
  }

  check(loginRes, {
    'login contains csrf': (r) => /"csrf"\s*:/.test(r.body),
  });

  return { csrf, grantId: 'MISSING', cartId: 'MISSING', etag: 'MISSING', hasCart: false };
}

function getCatalog(csrf) {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, {
    tags: { name: 'catalog' },
  });
  check(catalogRes, {
    'catalog status 200': (r) => r.status === 200,
  });

  const selection = extractProductAndVariant(catalogRes.body);
  if (selection) {
    return { product: selection.product, variant: selection.variant, csrf };
  }

  // Fallback: try /v2/catalog/page
  const pageRes = http.get(`${BASE_URL}/v2/catalog/page`, {
    tags: { name: 'catalog-page' },
  });
  const pageSelection = extractProductAndVariant(pageRes.body);
  if (pageSelection) {
    return { product: pageSelection.product, variant: pageSelection.variant, csrf };
  }

  return { product: 'MISSING', variant: 'MISSING', csrf };
}

function createCart(csrf, product, variant, grantId) {
  const payload = {
    product_id: product,
    variant_id: variant,
  };
  if (grantId && grantId !== 'MISSING') {
    payload.grant_id = grantId;
  }

  const cartRes = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    tags: { name: 'create-cart' },
  });

  check(cartRes, {
    'create-cart status 201': (r) => r.status === 201,
    'create-cart contains cart id': (r) => /"id"\s*:\s*"cart-/.test(r.body),
  });

  const newCsrf = extractCsrf(cartRes.body, csrf);
  const cartId = extractCartId(cartRes.body, 'MISSING');
  const etag = extractEtag(cartRes.headers, 'MISSING');

  return { csrf: newCsrf, cartId, etag, hasCart: cartId !== 'MISSING' };
}

function createOrder(csrf, cartId, etag, idempotencyKey) {
  const orderRes = http.post(
    `${BASE_URL}/v2/orders`,
    JSON.stringify({ cart_id: cartId }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
        'Idempotency-Key': idempotencyKey,
        ...(etag !== 'MISSING' ? { 'If-Match': etag } : {}),
      },
      tags: { name: 'create-order' },
    }
  );

  check(orderRes, {
    'create-order accepted true': (r) => r.status === 201 && /"accepted"\s*:\s*true/.test(r.body),
  });

  const newCsrf = extractCsrf(orderRes.body, csrf);
  return { csrf: newCsrf, orderRes };
}

function doWork(csrf) {
  const workRes = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    tags: { name: 'work' },
  });

  // Track business failure metric
  workResponses.add(1);
  const error = extractError(workRes.body);
  const isScheduled429 = workRes.status === 429;
  const isExpectedExpiry = error === 'expired' || error === 'session';

  if (!isScheduled429 && !isExpectedExpiry && workRes.status !== 200) {
    workUnexpectedFailures.add(1);
  }

  // Update business failure rate
  businessFailure.add(workUnexpectedFailures.value / workResponses.value);

  return { csrf, workRes };
}

export default function () {
  const threadNum = (__VU - 1) % 16 + 1;
  const username = `bench-${threadNum}`;

  group('journey', function () {
    // Fresh login
    let state = freshLogin(username);
    let csrf = state.csrf;
    let grantId = state.grantId;
    let cartId = state.cartId;
    let etag = state.etag;
    let hasCart = state.hasCart;

    // Get catalog
    const catalogResult = getCatalog(csrf);
    csrf = catalogResult.csrf;
    const product = catalogResult.product;
    const variant = catalogResult.variant;

    // Create cart
    const cartResult = createCart(csrf, product, variant, grantId);
    csrf = cartResult.csrf;
    cartId = cartResult.cartId;
    etag = cartResult.etag;
    hasCart = cartResult.hasCart;

    // Create order
    if (hasCart && cartId !== 'MISSING') {
      const orderResult = createOrder(csrf, cartId, etag, cartId);
      csrf = orderResult.csrf;
    }

    // Do work
    const workResult = doWork(csrf);
    csrf = workResult.csrf;
  });

  sleep(0.1);
}
