function extractCsrfFromHtml(html) {
  const match = html.match(/<input[^>]*\bname=["']csrf["'][^>]*\bvalue=["']([^"']+)["'][^>]*>/i);
  if (match) return match[1];
  const match2 = html.match(/<input[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']csrf["'][^>]*>/i);
  return match2 ? match2[1] : null;
}

function extractLocation(headers) {
  const loc = headers['Location'];
  return loc || null;
}

function extractEtag(headers) {
  const etag = headers['ETag'];
  return etag || null;
}

function extractError(body) {
  const match = body.match(/"error"\s*:\s*"(expired|session)"/);
  return match ? match[1] : null;
}

function extractJsonPath(body, path) {
  try {
    const data = JSON.parse(body);
    if (path === '$.csrf') return data.csrf || null;
    if (path === '$.grant_id') return data.grant_id || null;
    if (path === '$.id') return data.id || null;
    if (path === '$.data.products[?(@.variants[0].in_stock == true)].id') {
      const products = data.data && data.data.products;
      if (products) {
        for (const p of products) {
          if (p.variants && p.variants[0] && p.variants[0].in_stock === true) {
            return p.id;
          }
        }
      }
      return null;
    }
    if (path === '$.data.products[?(@.variants[0].in_stock == true)].variants[0].id') {
      const products = data.data && data.data.products;
      if (products) {
        for (const p of products) {
          if (p.variants && p.variants[0] && p.variants[0].in_stock === true) {
            return p.variants[0].id;
          }
        }
      }
      return null;
    }
    return null;
  } catch (e) {
    return null;
  }
}

function makeRequest(method, path, body, headers, opts = {}) {
  const url = path.startsWith('http') ? path : `${BASE_URL}${path}`;
  const params = {
    headers: Object.assign({}, headers),
    redirects: 0,
    timeout: '3s',
  };
  if (body !== null && body !== undefined) {
    if (typeof body === 'string') {
      params.headers['Content-Type'] = 'application/json';
    }
  }
  const res = http.request(method, url, body, params);
  return res;
}

function loginForm(state) {
  const res = makeRequest('GET', '/v2/login-form', null, {});
  const csrf = extractCsrfFromHtml(res.body);
