function login(state, username) {
  const payload = JSON.stringify({ username, password: 'bench', csrf: state.formCsrf || state.csrf });
  const res = makeRequest('POST', '/v2/login', payload, {
    'X-CSRF-Token': state.csrf,
  });
  const csrf = extractJsonPath(res.body, '$.csrf');
  if (csrf) state.csrf = csrf;
  const loc = extractLocation(res.headers);
  if (loc) {
