  // Initial login form
  const formRes = makeRequest('GET', '/v2/login-form', null, {});
  const formCsrf = extractCsrfFromHtml(formRes.body);
  if (formCsrf) state.formCsrf = formCsrf;
  if (formCsrf) state.csrf = formCsrf;

  // Initial login
  const loginRes = login(state, username);
  check(loginRes, { 'login has csrf': (r) => r.body.includes('"csrf"') });

  // Follow redirect if present
  if (state.redirect) {
    followRedirect(state);
  }

  // Get catalog
  const catalogRes = getCatalog(state);

  // Create cart
  const cartRes = createCart(state);
  check(cartRes, { 'cart created': (r) => r.body.includes('"id"') && r.body.includes('cart-') });

  // Post order (initial attempt)
  let orderRes = postOrder(state);
  check(orderRes, { 'order accepted': (r) => r.body.includes('"accepted"') && r.body.includes('true') });

  // Recovery branch if expired/session error
  if (state.recover) {
    // Renew session
    const renewRes = renewSession(state);

    // If renew also failed with expired/session, do fresh login
    if (state.recover) {
