    // Recover cart if exists
    if (state.hasCart) {
      recoverCart(state);
    }

    // Retry order once
    orderRes = postOrder(state);
    check(orderRes, { 'order accepted after recovery': (r) => r.body.includes('"accepted"') && r.body.includes('true') });
