  {"username": "bench-16", "password": "bench", "quantity": 17}
];

const failure = new Rate('business_failure');

export const options = {
  "scenarios": {
    "journeys": {
      "executor": "per-vu-iterations",
      "vus": 2,
      "iterations": 2,
      "maxDuration": "30s"
    }
  },
  "thresholds": {"checks": ["rate==1"]}
};

const base = __ENV.BASE_URL;

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function raw(path, method = 'GET', data = null, extra = {}, csrfToken) {
  const headers = Object.assign(
    {'Content-Type': 'application/json'},
    csrfToken ? {'X-CSRF-Token': csrfToken} : {},
    extra
  );
  const r = http.request(
    method,
    base + path,
    data === null ? null : JSON.stringify(data),
    {headers: headers, redirects: 0, timeout: '3s'}
  );
  const b = body(r);
  if (path === '/v2/work') {
    failure.add(r.status >= 400 && !(r.status === 401 && b.error === 'expired') && r.status !== 429);
  }
  return r;
}

function login(state) {
  let r = raw('/v2/login-form', 'GET', null, {}, null);
  const token = r.html().find('input[name="csrf"]').first().attr('value');
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {username: row.username, password: row.password, csrf: token}, {}, token);
  if (r.status === 302) {
    r = raw(r.headers.Location, 'GET', null, {}, body(r).csrf || token);
    state.grant = body(r).grant_id;
  }
  const b = body(r);
  if (b.csrf) state.csrf = b.csrf;
  check(r, {'login': r => r.status === 200});
}

function request(state, path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra, state.csrf);
  const b = body(r);
  if (b.csrf) state.csrf = b.csrf;

  if (r.status === 401 && ['expired', 'session'].indexOf(b.error) >= 0) {
    const renewed = raw('/v2/session/renew', 'POST', {}, {}, state.csrf);
    const rb = body(renewed);
    if (rb.csrf) state.csrf = rb.csrf;
    if (renewed.status !== 200) {
      login(state);
    }
    if (state.cart) {
      raw('/v2/carts/' + state.cart + '/recover', 'POST', {}, {}, state.csrf);
    }
    r = raw(path, method, data, extra, state.csrf);
    const rb2 = body(r);
    if (rb2.csrf) state.csrf = rb2.csrf;
  }
  return r;
}

function work(state, override) {
  if (cfg.workload || !state.csrf) login(state);
  const path = override || cfg.path || '/v2/work';
  let r = request(state, path, 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    sleep(Number(r.headers['Retry-After']) + 0.01);
    r = request(state, path, 'POST', {});
  }
  check(r, {
    'operation or expected throttle': r =>
      (r.status === 200 && body(r).ok === true) || (cfg.completion && r.status === 429)
  });
}

function flow() {
  // Fresh state per iteration: new login, new cart, no carry-over.
  const state = {csrf: '', cart: '', grant: ''};

  login(state);

  if (cfg.mode === 'challenge') {
    let r = request(state, '/v2/challenge-form');
    const form = r.html().find('form');
    const token = form.find('input[name="challenge"]').first().attr('value');
    r = request(state, form.attr('action'), 'POST', {challenge: token});
    r = request(state, r.headers.Location);
    state.grant = body(r).grant_id;
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product;
  for (let n = 0; n < 3 && page; n++) {
    const b = body(request(state, page));
    product = b.data.products.find(p => p.variants.some(v => v.in_stock));
    if (product) break;
    page = b.next;
  }
  if (!product) {
    check(false, {'eligible product': x => x});
    return;
  }

  const variant = product.variants.find(v => v.in_stock);
  let r = request(state, '/v2/carts', 'POST', {
    product_id: product.id,
    variant_id: variant.id,
    grant_id: state.grant
  });
  state.cart = body(r).id;
  let etag = r.headers.Etag;
  check(r, {'cart': r => r.status === 201});

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data' ? rows[(__VU - 1) % rows.length].quantity : (cfg.quantity || 2);
    r = request(state, '/v2/carts/' + state.cart, 'PATCH', {quantity: quantity}, {'If-Match': etag});
    if (r.status === 412) {
      etag = request(state, '/v2/carts/' + state.cart).headers.Etag;
      r = request(state, '/v2/carts/' + state.cart, 'PATCH', {quantity: quantity}, {'If-Match': etag});
    }
    etag = r.headers.Etag;
    check(r, {'update': r => r.status === 200});
  }

  let reservation;
  if (cfg.mode === 'reservation') {
    r = request(state, '/v2/reservations', 'POST', {cart_id: state.cart});
    const url = body(r).status_url;
    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(state, url);
      const b = body(r);
      if (b.status === 'ready') {
        reservation = b.reservation_id;
        break;
      }
      if (b.status === 'failed') {
        check(false, {'reservation ready': x => x});
        return;
      }
    }
    if (!reservation) return;
  }

  r = request(state, '/v2/orders', 'POST', {
    cart_id: state.cart,
    reservation_id: reservation
  }, {'Idempotency-Key': state.cart, 'If-Match': etag});
  check(r, {'accepted': r => r.status === 201 && body(r).accepted === true});

  if (cfg.mode === 'threshold') raw('/v2/health');
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work({csrf: '', cart: '', grant: ''});
  } else if (cfg.mode === 'errors') {
    const state = {csrf: '', cart: '', grant: ''};
    login(state);
    for (let n = 0; n < 4; n++) work(state);
  } else {
    flow();
  }
}

export function browse() {
  work({csrf: '', cart: '', grant: ''}, '/v2/browse');
}

export function checkout() {
  flow();
}
