    tags: { name: 'work' }
  });

  const endTime = Date.now();
  workLatency.add(endTime - startTime);

  // Check for scheduled 429
  if (workRes.status === 429) {
    // Scheduled 429 - retry after 1s, up to 4 retries
    let retryCount = 0;
    let retryRes = workRes;

    while (retryRes.status === 429 && retryCount < 4) {
      sleep(1);
      retryCount++;
      retryRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf
        },
        tags: { name: 'work_retry' }
      });
