      workCompletions.add(1);
      return { success: true, status: 200, csrf: csrf };
    } else if (retryRes.status === 429) {
      // Still 429 after retries - expected, not a completion
      return { success: false, status: 429, expected: true, csrf: csrf };
    } else {
      unexpectedErrors.add(1);
      businessFailures.add(1);
      return { success: false, status: retryRes.status, expected: false, csrf: csrf };
    }
  }

  if (workRes.status === 200) {
    workCompletions.add(1);
    let newCsrf = csrf;
    try {
      const workData = JSON.parse(workRes.body);
      if (workData.csrf) {
        newCsrf = workData.csrf;
      }
    } catch (e) {
      // No CSRF in response
    }
    return { success: true, status: 200, csrf: newCsrf };
  }

  if (workRes.status === 401) {
    // Check if expired
    let errorType = 'unknown';
    try {
      const errorData = JSON.parse(workRes.body);
      errorType = errorData.error || 'unknown';
    } catch (e) {
      // Try to parse from response
    }

    if (errorType === 'expired') {
      // Session expired - renew
      const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf
        },
        tags: { name: 'session_renew' }
      });

