        // Retry work once
        const retryWorkRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': newCsrf
          },
          tags: { name: 'work_retry_after_renew' }
        });

        if (retryWorkRes.status === 200) {
          workCompletions.add(1);
          return { success: true, status: 200, csrf: newCsrf };
        } else if (retryWorkRes.status === 429) {
          return { success: false, status: 429, expected: true, csrf: newCsrf };
        } else {
          unexpectedErrors.add(1);
          businessFailures.add(1);
          return { success: false, status: retryWorkRes.status, expected: false, csrf: newCsrf };
        }
      }
    }

    // Other 401 errors
    unexpectedErrors.add(1);
    businessFailures.add(1);
    return { success: false, status: 401, expected: false, csrf: csrf };
  }

  // Other errors
  unexpectedErrors.add(1);
  businessFailures.add(1);
  return { success: false, status: workRes.status, expected: false, csrf: csrf };
}

