    redirects: 0,
    tags: { route: 'cart-patch' }
  });

  if (patchRes.status === 401) {
    const body = patchRes.body;
    if (body.includes('error=expired')) {
      return handle401(state, () => updateCartQuantity(state, quantity));
    }
    return false;
  }

  if (patchRes.status === 412) {
    // Re-read and retry once
    if (getCart(state)) {
      const retryHeaders = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrfToken,
        'If-Match': state.cartEtag
      };
      const retryRes = http.patch(`${BASE_URL}/v2/carts/${state.cartId}`, payload, {
        headers: retryHeaders,
        redirects: 0,
        tags: { route: 'cart-patch-retry' }
      });

      if (retryRes.status === 401) {
        const retryBody = retryRes.body;
        if (retryBody.includes('error=expired')) {
          return handle401(state, () => updateCartQuantity(state, quantity));
        }
        return false;
      }

      if (retryRes.status === 200) {
        try {
          const body = JSON.parse(retryRes.body);
          if (body.csrf) {
            state.csrfToken = body.csrf;
          }
          state.cartEtag = retryRes.headers['ETag'] || retryRes.headers['etag'] || null;
          return true;
        } catch (e) {
          return false;
        }
      }
    }
    return false;
  }

  if (patchRes.status === 200) {
    try {
      const body = JSON.parse(patchRes.body);
      if (body.csrf) {
        state.csrfToken = body.csrf;
      }
      state.cartEtag = patchRes.headers['ETag'] || patchRes.headers['etag'] || null;
      return true;
    } catch (e) {
      return false;
    }
  }

  return false;
}

function getChallengeForm(state) {
  const challengeRes = http.get(`${BASE_URL}/v2/challenge-form`, {
    redirects: 0,
    tags: { route: 'challenge-form' }
  });

  if (challengeRes.status === 401) {
    const body = challengeRes.body;
    if (body.includes('error=expired')) {
      return handle401(state, () => getChallengeForm(state));
    }
    return false;
  }

  if (challengeRes.status !== 200) {
    return false;
  }

  const challengeInfo = getChallengeFromForm(challengeRes.body);
  if (challengeInfo) {
    state.challengeFormAction = challengeInfo.action;
    state.challengeId = challengeInfo.challenge;
    return true;
  }

  return false;
}

function submitChallenge(state) {
  if (!state.challengeFormAction || !state.challengeId) {
    return false;
  }

  const actionUrl = state.challengeFormAction.startsWith('http') 
    ? state.challengeFormAction 
    : `${BASE_URL}${state.challengeFormAction}`;

  const payload = JSON.stringify({ challenge: state.challengeId });

  const challengeRes = http.post(actionUrl, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrfToken
    },
    redirects: 0,
    tags: { route: 'challenge-submit' }
  });

  if (challengeRes.status === 401) {
    const body = challengeRes.body;
    if (body.includes('error=expired')) {
      return handle401(state, () => submitChallenge(state));
    }
    return false;
  }

  if (challengeRes.status === 302) {
    const location = getLocationFromHeaders(challengeRes.headers);
    if (location) {
      const followUrl = location.startsWith('http') ? location : `${BASE_URL}${location}`;
      const followRes = http.get(followUrl, {
        redirects: 0,
        tags: { route: 'challenge-follow' }
      });

      if (followRes.status === 200) {
        try {
          const body = JSON.parse(followRes.body);
          if (body.grant_id) {
            state.grantId = body.grant_id;
          }
          if (body.csrf) {
            state.csrfToken = body.csrf;
          }
          return true;
        } catch (e) {
          return false;
        }
      }
    }
  }

  return false;
}

function createReservation(state) {
  if (!state.cartId) {
    return false;
  }

  const payload = JSON.stringify({ cart_id: state.cartId });

  const resRes = http.post(`${BASE_URL}/v2/reservations`, payload, {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrfToken
    },
    redirects: 0,
    tags: { route: 'reservation-create' }
  });

  if (resRes.status === 401) {
    const body = resRes.body;
    if (body.includes('error=expired')) {
      return handle401(state, () => createReservation(state));
    }
    return false;
  }

  if (resRes.status !== 202) {
    return false;
  }

  try {
    const body = JSON.parse(resRes.body);
    if (body.csrf) {
      state.csrfToken = body.csrf;
    }

    const statusUrl = body.status_url;
    if (!statusUrl) return false;

    // Poll at least 50ms apart, at most 5 times
    for (let i = 0; i < 5; i++) {
      sleep(0.05);

      const pollUrl = statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`;
      const pollRes = http.get(pollUrl, {
        redirects: 0,
        tags: { route: 'reservation-poll' }
      });

      if (pollRes.status === 401) {
        const pollBody = pollRes.body;
        if (pollBody.includes('error=expired')) {
          return handle401(state, () => createReservation(state));
        }
        return false;
      }

      if (pollRes.status === 200) {
        try {
          const pollBody = JSON.parse(pollRes.body);
          if (pollBody.csrf) {
            state.csrfToken = pollBody.csrf;
          }

          if (pollBody.status === 'ready') {
            state.reservationId = pollBody.reservation_id;
            return true;
          } else if (pollBody.status === 'failed') {
            return false;
          }
          // pending - continue polling
        } catch (e) {
          return false;
        }
      }
    }

    return false;
  } catch (e) {
    return false;
  }
}

function createOrder(state) {
  if (!state.cartId || !state.idempotencyKey) {
    return false;
  }

  const payload = {
    cart_id: state.cartId
  };

  if (state.reservationId) {
    payload.reservation_id = state.reservationId;
  }

  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrfToken,
    'Idempotency-Key': state.idempotencyKey
  };

  if (state.cartEtag) {
    headers['If-Match'] = state.cartEtag;
  }

  const orderRes = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
    redirects: 0,
    tags: { route: 'order-create' }
  });

  if (orderRes.status === 401) {
    const body = orderRes.body;
    if (body.includes('error=expired')) {
      return handle401(state, () => createOrder(state));
    }
    return false;
  }

  if (orderRes.status === 201) {
    try {
      const body = JSON.parse(orderRes.body);
      if (body.accepted === true) {
        if (body.csrf) {
          state.csrfToken = body.csrf;
        }
        return true;
      }
      return false;
    } catch (e) {
      return false;
    }
  }

  if (orderRes.status === 200) {
    try {
      const body = JSON.parse(orderRes.body);
      if (body.accepted === false) {
        return false; // Business failure
      }
      if (body.accepted === true) {
        if (body.csrf) {
          state.csrfToken = body.csrf;
        }
        return true;
      }
    } catch (e) {
      return false;
    }
  }

  return false;
}

function performWork(state) {
  if (!state.authenticated || !state.csrfToken) {
    return { status: 'not_authenticated' };
  }

  const startTime = Date.now();

  const workRes = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrfToken
    },
    redirects: 0,
    tags: { route: 'work' }
  });

  const endTime = Date.now();
  workResponseTime.add(endTime - startTime);

  if (workRes.status === 401) {
    const body = workRes.body;
    if (body.includes('error=expired')) {
      // Handle expiry
      const renewSuccess = renewSession(state);
      if (renewSuccess) {
        if (state.cartId) {
          recoverCart(state);
        }
        // Retry work once
        const retryStart = Date.now();
        const retryRes = http.post(`${BASE_URL}/v2/work`, '{}', {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrfToken
          },
          redirects: 0,
          tags: { route: 'work-retry' }
        });
        const retryEnd = Date.now();
        workResponseTime.add(retryEnd - retryStart);

        if (retryRes.status === 200) {
          try {
            const body = JSON.parse(retryRes.body);
            if (body.ok === true) {
              if (body.csrf) {
                state.csrfToken = body.csrf;
              }
              return { status: 'success', startTime: retryStart };
            }
          } catch (e) {
            return { status: 'unexpected_error' };
          }
        } else if (retryRes.status === 429) {
          return { status: 'scheduled_429', retryAfter: 1 };
        } else if (retryRes.status >= 500) {
          return { status: 'unexpected_error' };
        } else {
          return { status: 'unexpected_error' };
        }
      }

      // Session revoked
      state.authenticated = false;
      state.csrfToken = null;
      const loginSuccess = login(state);
      if (loginSuccess && state.cartId) {
        recoverCart(state);
        // Retry work once
        const retryStart2 = Date.now();
        const retryRes2 = http.post(`${BASE_URL}/v2/work`, '{}', {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrfToken
          },
          redirects: 0,
          tags: { route: 'work-retry2' }
        });
        const retryEnd2 = Date.now();
        workResponseTime.add(retryEnd2 - retryStart2);

        if (retryRes2.status === 200) {
          try {
            const body = JSON.parse(retryRes2.body);
            if (body.ok === true) {
              if (body.csrf) {
                state.csrfToken = body.csrf;
              }
              return { status: 'success', startTime: retryStart2 };
            }
          } catch (e) {
            return { status: 'unexpected_error' };
          }
        } else if (retryRes2.status === 429) {
          return { status: 'scheduled_429', retryAfter: 1 };
        } else if (retryRes2.status >= 500) {
          return { status: 'unexpected_error' };
        } else {
          return { status: 'unexpected_error' };
        }
      }

      return { status: 'auth_failed' };
    }

    if (body.includes('error=denied')) {
      return { status: 'denied' };
    }

    return { status: 'auth_failed' };
  }

  if (workRes.status === 200) {
    try {
      const body = JSON.parse(workRes.body);
      if (body.ok === true) {
        if (body.csrf) {
          state.csrfToken = body.csrf;
        }
        return { status: 'success', startTime: startTime };
      }
      return { status: 'unexpected_error' };
    } catch (e) {
      return { status: 'unexpected_error' };
    }
  }

  if (workRes.status === 429) {
    return { status: 'scheduled_429', retryAfter: 1 };
  }

  if (workRes.status >= 500) {
    return { status: 'unexpected_error' };
  }

  return { status: 'unexpected_error' };
}

function fullJourney(state) {
  // Fresh login
  state.authenticated = false;
  state.csrfToken = null;
  state.cartId = null;
  state.cartEtag = null;
  state.grantId = null;
  state.reservationId = null;
  state.idempotencyKey = null;
  state.challengeId = null;
  state.challengeFormAction = null;

  const loginSuccess = login(state);
  if (!loginSuccess) {
    return false;
  }

  // Get catalog
  const products = getCatalog(state);
  if (!products || products.length === 0) {
    return false;
  }

  // Pick first product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;

  for (const product of products) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    // Try catalog pages
    let pageUrl = '/v2/catalog/page';
    for (let i = 0; i < 3; i++) {
      const pageData = getCatalogPage(state, pageUrl);
      if (pageData && pageData.data && pageData.data.products) {
        for (const product of pageData.data.products) {
          if (product.variants && product.variants.length > 0) {
            for (const variant of product.variants) {
              if (variant.in_stock) {
                selectedProduct = product;
                selectedVariant = variant;
                break;
              }
            }
            if (selectedProduct) break;
          }
        }
        if (selectedProduct) break;
      }
      if (pageData && pageData.next) {
        pageUrl = pageData.next;
      } else {
        break;
      }
    }
  }

  if (!selectedProduct || !selectedVariant) {
    return false;
  }

  // Get challenge form and submit
  if (getChallengeForm(state)) {
    submitChallenge(state);
  }

  // Create cart
  if (!createCart(state, selectedProduct.id, selectedVariant.id)) {
    return false;
  }

  // Update cart quantity
  if (!updateCartQuantity(state, 1)) {
    return false;
  }

  // Create reservation
  if (!createReservation(state)) {
    return false;
  }

  // Create order
  if (!createOrder(state)) {
    return false;
  }

  return true;
}

export const options = {
  scenarios: {
    workload: {
      executor: 'constant-arrival-rate',
      rate: TARGET_RATE,
      timeUnit: '1s',
      duration: `${WARMUP_SECONDS + SCORED_SECONDS + DRAIN_SECONDS}s`,
      preAllocatedVUs: 2,
      maxVUs: MAX_VUS,
    },
  },
  thresholds: {},
};

// Track T0 (first authenticated eligible POST)
let t0 = null;
let t0Set = false;

export default function () {
  const state = getVUState();

  // Perform full journey to get authenticated
  const journeySuccess = fullJourney(state);

  if (!journeySuccess) {
    droppedWork.add(1);
    return;
  }

  // Now perform work
  const workResult = performWork(state);

  if (workResult.status === 'success') {
    workStarts.add(1);
    workCompletions.add(1);

    // Record start timestamp for scoring
    if (!t0Set && workResult.startTime) {
      t0 = workResult.startTime;
      t0Set = true;
      console.log(`T0 set to: ${t0}`);
    }

    operationStarts.push(workResult.startTime);
    operationCompletions.push(Date.now());
  } else if (workResult.status === 'scheduled_429') {
    // Scheduled 429 - retry with Retry-After
    let retries = 0;
    let success = false;

    while (retries < MAX_RETRIES_429 && !success) {
      sleep(RETRY_AFTER_SECONDS);

      const retryResult = performWork(state);

      if (retryResult.status === 'success') {
        workStarts.add(1);
        workCompletions.add(1);

        if (!t0Set && retryResult.startTime) {
          t0 = retryResult.startTime;
          t0Set = true;
          console.log(`T0 set to: ${t0}`);
        }

        operationStarts.push(retryResult.startTime);
        operationCompletions.push(Date.now());
        success = true;
      } else if (retryResult.status === 'scheduled_429') {
        retries++;
      } else {
        // Unexpected error
        workFailures.add(1);
        businessFailureRate.add(1);
        droppedWork.add(1);
        operationFailures.push(Date.now());
        break;
      }
    }

    if (!success && retries >= MAX_RETRIES_429) {
      droppedWork.add(1);
      workFailures.add(1);
      businessFailureRate.add(1);
      operationFailures.push(Date.now());
    }
  } else if (workResult.status === 'unexpected_error') {
    workFailures.add(1);
    businessFailureRate.add(1);
    droppedWork.add(1);
    operationFailures.push(Date.now());
  } else if (workResult.status === 'denied') {
    // Denied is not expiry - fail assertion
    workFailures.add(1);
    businessFailureRate.add(1);
    droppedWork.add(1);
    operationFailures.push(Date.now());
  } else {
    // auth_failed or not_authenticated
    droppedWork.add(1);
    operationFailures.push(Date.now());
  }
}

export function setup() {
  // Record owner seeds
  const ownerSeeds = [];
  for (let i = 1; i <= 16; i++) {
    ownerSeeds.push(`bench-${i}`);
  }

  return { ownerSeeds: ownerSeeds };
}

export function teardown(data) {
  // Output scoring data
  console.log('=== SCORING DATA ===');
  console.log(`T0: ${t0}`);
  console.log(`Total work starts: ${workStarts.value}`);
  console.log(`Total work completions: ${workCompletions.value}`);
  console.log(`Total work failures: ${workFailures.value}`);
  console.log(`Total dropped work: ${droppedWork.value}`);
  console.log(`Business failure rate: ${businessFailureRate.value}`);

  if (t0) {
    // Calculate windows
    const windows = [];
    for (let i = 0; i < TOTAL_SCORED_WINDOWS; i++) {
      const windowStart = t0 + WARMUP_SECONDS * 1000 + i * WINDOW_SECONDS * 1000;
      const windowEnd = windowStart + WINDOW_SECONDS * 1000;

      const startsInWindow = operationStarts.filter(ts => ts >= windowStart && ts < windowEnd).length;
      const completionsInWindow = operationCompletions.filter(ts => ts >= windowStart && ts < windowEnd).length;
      const failuresInWindow = operationFailures.filter(ts => ts >= windowStart && ts < windowEnd).length;

      windows.push({
        window: i,
        starts: startsInWindow,
        completions: completionsInWindow,
        failures: failuresInWindow
      });
    }

    console.log('Windows:');
    windows.forEach(w => {
      console.log(`  Window ${w.window}: starts=${w.starts}, completions=${w.completions}, failures=${w.failures}`);
    });

    // Phase targets
    const phase1Target = PHASE_TARGETS[0] * 10; // 50 over 10 seconds
    const phase2Target = PHASE_TARGETS[1] * 10; // 150 over 10 seconds
    const phase3Target = PHASE_TARGETS[2] * 10; // 50 over 10 seconds

    const phase1Starts = windows.slice(0, 2).reduce((sum, w) => sum + w.starts, 0);
    const phase2Starts = windows.slice(2, 4).reduce((sum, w) => sum + w.starts, 0);
    const phase3Starts = windows.slice(4, 6).reduce((sum, w) => sum + w.starts, 0);

    console.log(`Phase 1 (0-10s): ${phase1Starts}/${phase1Target}`);
    console.log(`Phase 2 (10-20s): ${phase2Starts}/${phase2Target}`);
    console.log(`Phase 3 (20-30s): ${phase3Starts}/${phase3Target}`);
  }

  console.log(`Owner seeds: ${JSON.stringify(data.ownerSeeds)}`);
  console.log('=== END SCORING DATA ===');
}
