import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Counter } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const profiles = [
  { delay_seconds: 0.5 },
  { delay_seconds: 0.5, html_layout: 1, reverse_catalog: true }
];

const unexpectedErrors = new Rate('unexpected_errors');
const businessFailures = new Rate('business_failures');
const workCompletions = new Counter('work_completions');
const workAttempts = new Counter('work_attempts');

function getCsrfFromForm(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  return match ? match[1] : null;
}

function getLocationFromHeaders(headers) {
  const loc = headers['Location'] || headers['location'];
  return loc || null;
}

function login(username, password) {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });

  if (formRes.status !== 200) {
    unexpectedErrors.add(1);
    return null;
  }

  const csrf = getCsrfFromForm(formRes.body);
  if (!csrf) {
    unexpectedErrors.add(1);
    return null;
  }

  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' }
  });

  if (loginRes.status === 302) {
    const location = getLocationFromHeaders(loginRes.headers);
    if (location) {
      const followRes = http.get(location.startsWith('http') ? location : `${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'login_follow' }
      });
      if (followRes.status !== 200) {
        unexpectedErrors.add(1);
        return null;
      }
      try {
        const body = JSON.parse(followRes.body);
        return { csrf: body.csrf, user: body.user };
      } catch (e) {
        unexpectedErrors.add(1);
        return null;
      }
    }
  }

  if (loginRes.status === 200) {
    try {
      const body = JSON.parse(loginRes.body);
      return { csrf: body.csrf, user: body.user };
    } catch (e) {
      unexpectedErrors.add(1);
      return null;
    }
  }

  unexpectedErrors.add(1);
  return null;
}

function renewSession(currentCsrf) {
  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': currentCsrf
    },
    redirects: 0,
    tags: { name: 'session_renew' }
  });

  if (renewRes.status === 200) {
    try {
      const body = JSON.parse(renewRes.body);
      return { csrf: body.csrf || currentCsrf, renewed: true };
    } catch (e) {
      return { csrf: currentCsrf, renewed: false };
    }
  }

  return { csrf: currentCsrf, renewed: false };
}

function recoverCart(cartId, csrf) {
  if (!cartId) return;
  const recoverRes = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'cart_recover' }
  });
  return recoverRes.status < 400;
}

function getCatalog(csrf) {
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: { 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'catalog' }
  });

  if (res.status !== 200) return null;

  try {
    const body = JSON.parse(res.body);
    return body.data && body.data.products ? body.data.products : [];
  } catch (e) {
    return null;
  }
}

function getCatalogPage(csrf, pageUrl) {
  const url = pageUrl.startsWith('http') ? pageUrl : `${BASE_URL}${pageUrl}`;
  const res = http.get(url, {
    headers: { 'X-CSRF-Token': csrf },
    redirects: 0,
    tags: { name: 'catalog_page' }
  });

  if (res.status !== 200) return null;

  try {
    const body = JSON.parse(res.body);
    return body;
  } catch (e) {
    return null;
  }
}

function createCart(csrf, productId, variantId, grantId) {
  const payload = {
    product_id: productId,
    variant_id: variantId
  };
  if (grantId) payload.grant_id = grantId;

  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'cart_create' }
  });

