const retryAfterHonored = new Counter('retry_after_honored');
const scheduled429s = new Counter('scheduled_429s');

// Configuration
const USERS = 2;
const ITERATIONS = 2;
const TARGET_RATE = 8;
const RAW_CEILING = 12;
