const SCORE_DURATION = 30;
const WARMUP = 5;
const DRAIN = 5;
const MAX_RETRIES = 4;
const RETRY_AFTER_SECONDS = 1;

// Track per-user state
const userStates = {};

function getCSRFFromForm(html) {
  const match = html.match(/name=["']csrf["'][^>]*value=["']([^"']+)["']/i) ||
                 html.match(/value=["']([^"']+)["'][^>]*name=["']csrf["']/i);
  return match ? match[1] : null;
}

function getNonceFromForm(html) {
  const match = html.match(/name=["']login_nonce["'][^>]*value=["']([^"']+)["']/i) ||
                 html.match(/value=["']([^"']+)["'][^>]*name=["']login_nonce["']/i);
  return match ? match[1] : null;
}

function login(userIndex) {
  const username = `bench-${userIndex}`;
  const password = 'bench';

  // Get login form
  const formRes = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    tags: { name: 'login_form' }
  });

  if (formRes.status !== 200) {
    return null;
  }

  const csrf = getCSRFFromForm(formRes.body);
  if (!csrf) {
    return null;
  }

  // Login
  const loginRes = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
    username: username,
    password: password,
    csrf: csrf
  }), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf
    },
    redirects: 0,
    tags: { name: 'login' }
  });

  if (loginRes.status === 302) {
    const location = loginRes.headers['Location'];
    if (location) {
      const followRes = http.get(`${BASE_URL}${location}`, {
        redirects: 0,
        tags: { name: 'login_follow' }
      });
      if (followRes.status === 200) {
        try {
          const body = JSON.parse(followRes.body);
          return {
            csrf: body.csrf || csrf,
            user: body.user || username,
            cookies: followRes.cookies
          };
        } catch (e) {
          return { csrf: csrf, user: username, cookies: loginRes.cookies };
        }
      }
    }
  } else if (loginRes.status === 200) {
    try {
      const body = JSON.parse(loginRes.body);
      return {
        csrf: body.csrf || csrf,
        user: body.user || username,
        cookies: loginRes.cookies
      };
    } catch (e) {
      return { csrf: csrf, user: username, cookies: loginRes.cookies };
    }
  }

  return null;
}

function renewSession(userIndex) {
  const state = userStates[userIndex];
  if (!state) return false;

  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf
    },
    tags: { name: 'session_renew' }
  });

  if (renewRes.status === 200) {
    try {
      const body = JSON.parse(renewRes.body);
      if (body.csrf) {
        state.csrf = body.csrf;
      }
      return true;
    } catch (e) {
      return false;
    }
  }

  return false;
}

function doWork(userIndex) {
  const state = userStates[userIndex];
  if (!state) return;

  let retries = 0;
  let lastRetryAfter = 0;

  while (retries <= MAX_RETRIES) {
    const now = Date.now();

    // Check if we need to wait for Retry-After
    if (lastRetryAfter > 0) {
      const waitUntil = lastRetryAfter;
      if (now < waitUntil) {
        sleep((waitUntil - now) / 1000);
      }
      lastRetryAfter = 0;
    }

    workStarts.add(1);
    businessResponses.add(1);

    const workRes = http.post(`${BASE_URL}/v2/work`, JSON.stringify({}), {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf
      },
      tags: { name: 'work' }
    });

    if (workRes.status === 200) {
      try {
        const body = JSON.parse(workRes.body);
        if (body.ok === true) {
          workCompletions.add(1);
          if (body.csrf) {
            state.csrf = body.csrf;
          }
          return;
        }
      } catch (e) {
        // Parse error, treat as unexpected
        unexpectedErrors.add(1);
        return;
      }
    } else if (workRes.status === 429) {
      scheduled429s.add(1);
      const retryAfter = workRes.headers['Retry-After'];
      if (retryAfter) {
        const retryAfterSeconds = parseInt(retryAfter, 10);
        if (retryAfterSeconds > 0) {
          retryAfterHonored.add(1);
          lastRetryAfter = Date.now() + retryAfterSeconds * 1000;
          retries++;
          continue;
        }
      }
      // Default Retry-After of 1s
      retryAfterHonored.add(1);
      lastRetryAfter = Date.now() + RETRY_AFTER_SECONDS * 1000;
      retries++;
      continue;
    } else if (workRes.status === 401) {
      // Check error type
      try {
        const body = JSON.parse(workRes.body);
        if (body.error === 'expired') {
          // Renew session and retry once
          if (renewSession(userIndex)) {
            retries++;
            continue;
          }
        } else if (body.error === 'session') {
          // Session revoked, re-login
          const newState = login(userIndex);
          if (newState) {
            userStates[userIndex] = newState;
            retries++;
            continue;
          }
        } else if (body.error === 'denied') {
          // Not expiry, fail assertion
          unexpectedErrors.add(1);
          return;
        }
      } catch (e) {
        unexpectedErrors.add(1);
        return;
      }
      unexpectedErrors.add(1);
      return;
    } else if (workRes.status >= 500) {
      unexpectedErrors.add(1);
      return;
    } else {
      unexpectedErrors.add(1);
      return;
    }
  }

  // Exhausted retries
  unexpectedErrors.add(1);
}

