          state.lastLoginTime = Date.now();
          return true;
        } catch (e) {
          unexpectedErrors.add(1);
          return false;
        }
      }
    }
  } else if (loginRes.status === 200) {
    try {
      const body = JSON.parse(loginRes.body);
      state.csrf = body.csrf;
      state.loggedIn = true;
      state.lastLoginTime = Date.now();
      return true;
    } catch (e) {
      unexpectedErrors.add(1);
      return false;
    }
  }

  unexpectedErrors.add(1);
  return false;
}

function renewSession() {
  const state = getVUState();
  if (!state.csrf) return false;

  const renewRes = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
    headers: getHeaders(true),
  });

  if (renewRes.status === 200) {
    try {
      const body = JSON.parse(renewRes.body);
      if (body.csrf) {
        state.csrf = body.csrf;
      }
      state.lastLoginTime = Date.now();
      return true;
    } catch (e) {
      return false;
    }
  }

  return false;
}

function recoverCart() {
  const state = getVUState();
  if (!state.cartId || !state.csrf) return false;

  const recoverRes = http.post(`${BASE_URL}/v2/carts/${state.cartId}/recover`, JSON.stringify({}), {
    headers: getHeaders(true),
  });

  if (recoverRes.status === 200) {
    try {
      const body = JSON.parse(recoverRes.body);
      if (body.csrf) {
        state.csrf = body.csrf;
      }
      if (body.etag) {
        state.cartEtag = body.etag;
      }
      return true;
    } catch (e) {
      return false;
    }
  }

  return false;
}

function handle401(errorType, operation) {
  const state = getVUState();

  if (errorType === 'expired') {
    // Try renew
    if (renewSession()) {
      if (state.cartExists && state.cartId) {
        recoverCart();
      }
      return 'retry';
    }
    // Renew failed, try fresh login
    if (login()) {
      if (state.cartExists && state.cartId) {
        recoverCart();
      }
      return 'retry';
    }
    return 'fail';
  } else if (errorType === 'session') {
    // Session revoked
    if (login()) {
      if (state.cartExists && state.cartId) {
        recoverCart();
      }
      return 'retry';
    }
    return 'fail';
  } else if (errorType === 'denied') {
    return 'fail';
  }

  return 'fail';
}

function getCatalog() {
  const state = getVUState();
  const res = http.get(`${BASE_URL}/v2/catalog`, {
    headers: getHeaders(false),
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const action = handle401(errorType, 'catalog');
    if (action === 'retry') {
      return getCatalog();
    }
    return null;
  }

  if (res.status !== 200) {
    unexpectedErrors.add(1);
    return null;
  }

  try {
    const body = JSON.parse(res.body);
    if (body.data && body.data.products && body.data.products.length > 0) {
      return body.data.products;
