function parse401Error(res) {
  try {
    const body = JSON.parse(res.body);
    if (body.error === 'expired') return 'expired';
    if (body.error === 'session') return 'session';
    if (body.error === 'denied') return 'denied';
  } catch (e) {
    // ignore
  }
  return 'expired';
}

function createCart(productId, variantId) {
  const state = getVUState();
  const payload = {
    product_id: productId,
    variant_id: variantId,
  };
  if (state.grantId) {
    payload.grant_id = state.grantId;
