  const res = http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
    headers: getHeaders(true),
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const action = handle401(errorType, 'create_cart');
    if (action === 'retry') {
      return createCart(productId, variantId);
    }
    return false;
  }

  if (res.status !== 201) {
    unexpectedErrors.add(1);
    return false;
  }

  try {
    const body = JSON.parse(res.body);
    state.cartId = body.id;
    state.cartExists = true;
    if (body.csrf) {
      state.csrf = body.csrf;
    }
    if (res.headers['ETag']) {
      state.cartEtag = res.headers['ETag'];
    }
    return true;
  } catch (e) {
    unexpectedErrors.add(1);
    return false;
  }
}

function getCart() {
  const state = getVUState();
  if (!state.cartId) return false;

  const res = http.get(`${BASE_URL}/v2/carts/${state.cartId}`, {
    headers: getHeaders(false),
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const action = handle401(errorType, 'get_cart');
    if (action === 'retry') {
      return getCart();
    }
    return false;
  }

  if (res.status !== 200) {
    unexpectedErrors.add(1);
    return false;
  }

  if (res.headers['ETag']) {
    state.cartEtag = res.headers['ETag'];
  }
  return true;
}

function patchCart(quantity) {
  const state = getVUState();
  if (!state.cartId) return false;

  const headers = getHeaders(true);
  if (state.cartEtag) {
    headers['If-Match'] = state.cartEtag;
  }

  const res = http.patch(`${BASE_URL}/v2/carts/${state.cartId}`, JSON.stringify({
    quantity: quantity,
  }), {
    headers: headers,
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const action = handle401(errorType, 'patch_cart');
    if (action === 'retry') {
      return patchCart(quantity);
    }
    return false;
  }

  if (res.status === 412) {
    // Re-read and retry once
    if (getCart()) {
      const retryHeaders = getHeaders(true);
      if (state.cartEtag) {
        retryHeaders['If-Match'] = state.cartEtag;
      }
      const retryRes = http.patch(`${BASE_URL}/v2/carts/${state.cartId}`, JSON.stringify({
        quantity: quantity,
      }), {
        headers: retryHeaders,
      });

      if (retryRes.status === 401) {
        const errorType = parse401Error(retryRes);
        const action = handle401(errorType, 'patch_cart_retry');
        if (action === 'retry') {
          return patchCart(quantity);
        }
        return false;
      }

      if (retryRes.status === 200) {
        if (retryRes.headers['ETag']) {
          state.cartEtag = retryRes.headers['ETag'];
        }
        try {
          const body = JSON.parse(retryRes.body);
          if (body.csrf) {
            state.csrf = body.csrf;
          }
        } catch (e) {
          // ignore
        }
        return true;
      }

      unexpectedErrors.add(1);
      return false;
    }
    return false;
  }

  if (res.status !== 200) {
    unexpectedErrors.add(1);
    return false;
  }

  if (res.headers['ETag']) {
    state.cartEtag = res.headers['ETag'];
  }
  try {
    const body = JSON.parse(res.body);
    if (body.csrf) {
      state.csrf = body.csrf;
    }
  } catch (e) {
    // ignore
  }
  return true;
}

function getChallengeForm() {
  const state = getVUState();
  const res = http.get(`${BASE_URL}/v2/challenge-form`, {
    headers: { 'Accept': 'text/html' },
    redirects: 0,
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const action = handle401(errorType, 'challenge_form');
    if (action === 'retry') {
      return getChallengeForm();
    }
    return null;
  }

  if (res.status !== 200) {
    unexpectedErrors.add(1);
    return null;
  }

  // Extract form action and challenge input
  const actionMatch = res.body.match(/action="([^"]*\/v2\/challenges\/[^"]+)"/);
  const challengeMatch = res.body.match(/name="challenge"[^>]*value="([^"]+)"/);

  if (!actionMatch || !challengeMatch) {
    unexpectedErrors.add(1);
    return null;
  }

  return {
    action: actionMatch[1],
    challenge: challengeMatch[1],
  };
}

function submitChallenge(action, challengeValue) {
  const state = getVUState();
  const res = http.post(`${BASE_URL}${action}`, JSON.stringify({
    challenge: challengeValue,
  }), {
    headers: getHeaders(true),
    redirects: 0,
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const handleResult = handle401(errorType, 'challenge');
    if (handleResult === 'retry') {
      return submitChallenge(action, challengeValue);
    }
    return null;
  }

  if (res.status !== 302) {
    unexpectedErrors.add(1);
    return null;
  }

  const location = res.headers['Location'];
  if (!location) {
    unexpectedErrors.add(1);
    return null;
  }

  const followRes = http.get(`${BASE_URL}${location}`, {
    headers: getHeaders(false),
    redirects: 0,
  });

  if (followRes.status === 401) {
    const errorType = parse401Error(followRes);
    const handleResult = handle401(errorType, 'challenge_follow');
    if (handleResult === 'retry') {
      return submitChallenge(action, challengeValue);
    }
    return null;
  }

  if (followRes.status !== 200) {
    unexpectedErrors.add(1);
    return null;
  }

  try {
    const body = JSON.parse(followRes.body);
    if (body.grant_id) {
      state.grantId = body.grant_id;
    }
    if (body.csrf) {
      state.csrf = body.csrf;
    }
    return body.grant_id || null;
  } catch (e) {
    unexpectedErrors.add(1);
    return null;
  }
}

function createReservation() {
  const state = getVUState();
  if (!state.cartId) return false;

  const res = http.post(`${BASE_URL}/v2/reservations`, JSON.stringify({
    cart_id: state.cartId,
  }), {
    headers: getHeaders(true),
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const action = handle401(errorType, 'reservation');
    if (action === 'retry') {
      return createReservation();
    }
    return false;
  }

  if (res.status !== 202) {
    unexpectedErrors.add(1);
    return false;
  }

  try {
    const body = JSON.parse(res.body);
    if (body.csrf) {
      state.csrf = body.csrf;
    }
    if (body.status_url) {
      // Poll for status
      for (let i = 0; i < 5; i++) {
        sleep(0.05);
        const pollRes = http.get(`${BASE_URL}${body.status_url}`, {
          headers: getHeaders(false),
        });

        if (pollRes.status === 401) {
          const errorType = parse401Error(pollRes);
          const action = handle401(errorType, 'reservation_poll');
          if (action === 'retry') {
            continue;
          }
          return false;
        }

        if (pollRes.status !== 200) {
          unexpectedErrors.add(1);
          return false;
        }

        try {
          const pollBody = JSON.parse(pollRes.body);
          if (pollBody.status === 'ready' && pollBody.reservation_id) {
            state.reservationId = pollBody.reservation_id;
            if (pollBody.csrf) {
              state.csrf = pollBody.csrf;
            }
            return true;
          } else if (pollBody.status === 'failed') {
            return false;
          }
          // pending - continue polling
        } catch (e) {
          unexpectedErrors.add(1);
          return false;
        }
      }
    }
    return false;
  } catch (e) {
    unexpectedErrors.add(1);
    return false;
  }
}

function placeOrder() {
  const state = getVUState();
  if (!state.cartId) return false;

  state.idempotencyKey = `idem-${__VU}-${Date.now()}-${Math.random()}`;

  const payload = {
    cart_id: state.cartId,
  };
  if (state.reservationId) {
    payload.reservation_id = state.reservationId;
  }

  const headers = getHeaders(true);
  headers['Idempotency-Key'] = state.idempotencyKey;
  if (state.cartEtag) {
    headers['If-Match'] = state.cartEtag;
  }

  const res = http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
    headers: headers,
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const action = handle401(errorType, 'order');
    if (action === 'retry') {
      return placeOrder();
    }
    return false;
  }

  if (res.status === 201) {
    try {
      const body = JSON.parse(res.body);
      if (body.accepted === true && body.id) {
        if (body.csrf) {
          state.csrf = body.csrf;
        }
        return true;
      }
      // accepted: false is business failure
      businessFailures.add(1);
      return false;
    } catch (e) {
      unexpectedErrors.add(1);
      return false;
    }
  }

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.accepted === false) {
        businessFailures.add(1);
        return false;
      }
    } catch (e) {
      unexpectedErrors.add(1);
      return false;
    }
  }

  unexpectedErrors.add(1);
  return false;
}

function doBrowse() {
  const state = getVUState();

  if (!state.loggedIn) {
    if (!login()) {
      droppedWork.add(1);
      return;
    }
  }

  const res = http.post(`${BASE_URL}/v2/browse`, JSON.stringify({}), {
    headers: getHeaders(true),
  });

  if (res.status === 401) {
    const errorType = parse401Error(res);
    const action = handle401(errorType, 'browse');
    if (action === 'retry') {
      // Retry once
      const retryRes = http.post(`${BASE_URL}/v2/browse`, JSON.stringify({}), {
        headers: getHeaders(true),
      });
      if (retryRes.status === 200) {
        try {
          const body = JSON.parse(retryRes.body);
          if (body.ok === true) {
            browseStarts.add(1);
            if (body.csrf) {
              state.csrf = body.csrf;
            }
            return;
          }
        } catch (e) {
          // ignore
        }
      }
      droppedWork.add(1);
      return;
    }
    droppedWork.add(1);
    return;
  }

  if (res.status === 429) {
    // Scheduled 429 - retry with Retry-After
    const retryAfter = parseInt(res.headers['Retry-After'] || '1');
    for (let i = 0; i < 4; i++) {
      sleep(retryAfter);
      const retryRes = http.post(`${BASE_URL}/v2/browse`, JSON.stringify({}), {
        headers: getHeaders(true),
      });
      if (retryRes.status === 200) {
        try {
          const body = JSON.parse(retryRes.body);
          if (body.ok === true) {
            browseStarts.add(1);
            if (body.csrf) {
              state.csrf = body.csrf;
            }
            return;
          }
        } catch (e) {
          // ignore
        }
      } else if (retryRes.status === 429) {
        continue;
      } else if (retryRes.status === 401) {
        const errorType = parse401Error(retryRes);
        const action = handle401(errorType, 'browse_retry');
        if (action === 'retry') {
          continue;
        }
        droppedWork.add(1);
        return;
      } else {
        unexpectedErrors.add(1);
        droppedWork.add(1);
        return;
      }
    }
    droppedWork.add(1);
    return;
  }

  if (res.status === 200) {
    try {
      const body = JSON.parse(res.body);
      if (body.ok === true) {
        browseStarts.add(1);
        if (body.csrf) {
          state.csrf = body.csrf;
        }
        return;
      }
    } catch (e) {
      // ignore
    }
  }

  unexpectedErrors.add(1);
  droppedWork.add(1);
}

function doCheckout() {
  const state = getVUState();

  if (!state.loggedIn) {
    if (!login()) {
      droppedWork.add(1);
      return;
    }
  }

  // Reset cart state for fresh journey
  state.cartId = null;
  state.cartEtag = null;
  state.grantId = null;
  state.reservationId = null;
  state.cartExists = false;

  // Get catalog
  const products = getCatalog();
  if (!products || products.length === 0) {
    droppedWork.add(1);
    return;
  }

  // Select a product with in-stock variant
  let selectedProduct = null;
  let selectedVariant = null;

  const productList = PROFILE.reverse_catalog ? [...products].reverse() : products;

  for (const product of productList) {
    if (product.variants && product.variants.length > 0) {
      for (const variant of product.variants) {
        if (variant.in_stock) {
          selectedProduct = product;
          selectedVariant = variant;
          break;
        }
      }
      if (selectedProduct) break;
    }
  }

  if (!selectedProduct || !selectedVariant) {
    droppedWork.add(1);
    return;
  }

  // Create cart
  if (!createCart(selectedProduct.id, selectedVariant.id)) {
    droppedWork.add(1);
    return;
  }

  // Patch cart quantity
  if (!patchCart(1)) {
    droppedWork.add(1);
    return;
  }

  // Try to get challenge for grant
  const challengeForm = getChallengeForm();
  if (challengeForm) {
    const grantId = submitChallenge(challengeForm.action, challengeForm.challenge);
    if (grantId) {
      state.grantId = grantId;
    }
  }

  // Create reservation
  if (!createReservation()) {
    droppedWork.add(1);
    return;
  }

  // Apply checkout delay (slow after threshold)
  const elapsed = (Date.now() - state.lastLoginTime) / 1000;
  let delay = PROFILE.checkout_delay_seconds;
  if (elapsed > PROFILE.checkout_slow_after_seconds) {
    delay = PROFILE.checkout_slow_seconds;
  }
  sleep(delay);

  // Place order
  if (placeOrder()) {
    checkoutStarts.add(1);
    // Reset cart state after successful order
    state.cartId = null;
    state.cartEtag = null;
    state.grantId = null;
    state.reservationId = null;
    state.cartExists = false;
  } else {
    droppedWork.add(1);
  }
}

