export default function () {
  const state = getVUState();

  // Determine which operation to perform based on arrival rate
  // Browse: 8/s, Checkout: 2/s
  const rand = Math.random();
  if (rand < BROWSE_RATE / TOTAL_RATE) {
    doBrowse();
  } else {
    doCheckout();
  }
}
